import { useEffect, useMemo, useRef, useState } from "react";
import type { EventLogItem, InterfaceListItem, StreamListItem, StreamState } from "./types/api";
import type { Layout } from "react-grid-layout";
import { DashboardGrid } from "./components/DashboardGrid";
import { DetailPane } from "./components/DetailPane";
import { PinnedDetailPane } from "./components/PinnedDetailPane";
import { DEFAULT_EVENT_COLUMN_WIDTHS, EventLog, parseEventColumnWidths, type EventLogTab } from "./components/EventLog";
import { AppContextBar } from "./components/ui/AppContextBar";
import { PaneFrame, PaneHeader } from "./components/ui/PaneHeader";
import { SearchInput } from "./components/ui/SearchInput";
import { formatRelativeTime } from "./components/format";
import { InterfaceDetailPane } from "./components/InterfaceDetailPane";
import { StreamTable } from "./components/StreamTable";
import { TimelinePane } from "./components/TimelinePane";
import { TopologyPane } from "./components/TopologyPane";
import { MaintenancePane } from "./components/MaintenancePane";
import { ProtocolMapPane } from "./components/ProtocolMapPane";
import { AlertsPane } from "./components/AlertsPane";
import { useStreams } from "./hooks/useStreams";
import { getAppConfig, getDashboardLayouts, saveDashboardLayouts } from "./api/client";
import type { AppConfig, DashboardBreakpoint, DashboardCell, DashboardLayout, DashboardResponsiveLayouts, DashboardViewType, TimelineRow } from "./types/api";
import { matchesSearch } from "./components/search";
import { Icon, type IconName } from "./components/ui/Icon";
import { useI18n } from "./i18n";

type ExpandLevel = "interface" | "proto" | "stream" | "flow";
type DetailMode = "overview" | "detail";
type DashboardSelection = { streamKey: string; flowKey: string | null } | null;
type DashboardTargetPicker = { cellId: string; mode: "follow" | "pinned" } | null;
type MainTab = "dashboard" | "streams" | "detail" | "timeline" | "topology" | "events" | "preferences" | "maintenance" | "alerts" | "protocol-map" | "help" | "information";
type MenuPlacement = "top" | "center" | "bottom";
type MenuItem = {
  type: "item";
  key: MainTab;
  icon: IconName;
  label: string;
  hint: string;
  placement: MenuPlacement;
};
type MenuSeparator = { type: "separator"; key: string; placement: MenuPlacement };
type MenuEntry = MenuItem | MenuSeparator;
type StandaloneView = "streams" | "timeline" | "events" | "detail" | null;

const MENU_PLACEMENTS: MenuPlacement[] = ["top", "center", "bottom"];
const MENU_ITEMS: MenuEntry[] = [
  { type: "item", key: "dashboard", icon: "dashboard", label: "Dashboard", hint: "Overview panels", placement: "top" },
  { type: "item", key: "streams", icon: "streams", label: "Streams", hint: "Tree and filters", placement: "top" },
  { type: "item", key: "detail", icon: "detail", label: "Inspector", hint: "Metrics and flows", placement: "top" },
  { type: "item", key: "timeline", icon: "timeline", label: "Timeline", hint: "History bands", placement: "top" },
  { type: "item", key: "topology", icon: "topology", label: "Topology", hint: "Network map", placement: "top" },
  { type: "item", key: "events", icon: "events", label: "Events", hint: "Alerts and logs", placement: "top" },
  { type: "separator", key: "configuration", placement: "top" },
  { type: "item", key: "preferences", icon: "preferences", label: "Preferences", hint: "Application preferences", placement: "top" },
  { type: "item", key: "maintenance", icon: "maintenance", label: "Maintenance", hint: "STM runtime settings", placement: "top" },
  { type: "item", key: "alerts", icon: "alertRules", label: "Alert rules", hint: "STM thresholds and counter changes", placement: "top" },
  { type: "item", key: "protocol-map", icon: "protocolMap", label: "Protocol map", hint: "STM protocol classification", placement: "top" },
  { type: "separator", key: "information-section", placement: "bottom" },
  { type: "item", key: "help", icon: "help", label: "Help", hint: "Guides and operating instructions", placement: "bottom" },
  { type: "item", key: "information", icon: "information", label: "Information", hint: "Version and license information", placement: "bottom" }
];
const RANGE_OPTIONS = ["24h", "12h", "6h", "3h", "1h", "30m", "10m", "5m", "1m"];
const DEFAULT_DASHBOARD_LAYOUT: DashboardLayout = {
  id: "default",
  name: "Default dashboard", nameKey: "dashboard.defaultName",
  columns: 24,
  rowHeight: 32,
  cells: [
    { id: "streams", title: "Streams", titleKey: "nav.streams", viewType: "streams", grid: { x: 0, y: 0, w: 8, h: 11 } },
    { id: "detail", title: "Inspector", titleKey: "nav.inspector", viewType: "detail", grid: { x: 8, y: 0, w: 8, h: 11 } },
    { id: "topology", title: "Topology", titleKey: "nav.topology", viewType: "topology", grid: { x: 16, y: 0, w: 8, h: 11 } },
    { id: "timeline", title: "Timeline", titleKey: "nav.timeline", viewType: "timeline", grid: { x: 0, y: 11, w: 14, h: 8 } },
    { id: "events", title: "Events", titleKey: "nav.events", viewType: "events", grid: { x: 14, y: 11, w: 10, h: 8 } }
  ]
};


export function App() {
  const { locale, t } = useI18n();
  const initialParams = new URLSearchParams(window.location.search);
  const standaloneView = standaloneViewFromPath(window.location.pathname);
  const [activeTab, setActiveTab] = useState<MainTab>("dashboard");
  const [theme, setTheme] = useState<"light" | "dark">(() => {
    const saved = window.localStorage.getItem("stm-theme");
    return saved === "dark" ? "dark" : "light";
  });
  const [selectedStreamKey, setSelectedStreamKey] = useState<string | null>(() => initialParams.get("streamKey"));
  const [selectedFlowKey, setSelectedFlowKey] = useState<string | null>(() => initialParams.get("flowKey"));
  const [selectedInterfaceKey, setSelectedInterfaceKey] = useState<string | null>(() => initialParams.get("interfaceKey"));
  const [query, setQuery] = useState(() => initialParams.get("query") ?? "");
  const [expandLevel, setExpandLevel] = useState<ExpandLevel>(() => expandLevelFromParam(initialParams.get("expand")));
  const [timelineExpandLevel, setTimelineExpandLevel] = useState<ExpandLevel>(() => expandLevelFromParam(initialParams.get("timelineExpand") ?? initialParams.get("expand")));
  const [detailMode, setDetailMode] = useState<DetailMode>(() => detailModeFromParam(initialParams.get("mode")));
  const [metricsRange, setMetricsRange] = useState(() => rangeFromParam(initialParams.get("metricsRange") ?? initialParams.get("range"), "5m"));
//  const [timelineRange, setTimelineRange] = useState(() => rangeFromParam(initialParams.get("range"), "5m"));
  const [timelineRange, setTimelineRange] = useState(() => rangeFromParam(initialParams.get("range"), "1h"));
  const [eventsRange, setEventsRange] = useState(() => rangeFromParam(initialParams.get("range"), "24h"));
  const [dashboardRange, setDashboardRange] = useState(() => rangeFromParam(initialParams.get("dashboardRange"), "1h"));
  const [dashboardSelectedTimeSec, setDashboardSelectedTimeSec] = useState<number | null>(null);
  const [dashboardTimeSyncEnabled, setDashboardTimeSyncEnabled] = useState(false);
  const [dashboardPaused, setDashboardPaused] = useState(false);
  const [dashboardPauseTimeSec, setDashboardPauseTimeSec] = useState<number | null>(null);
  const [latestAvailableTimeSec, setLatestAvailableTimeSec] = useState<number | null>(null);
  const [timelineSortRefreshToken, setTimelineSortRefreshToken] = useState(0);
  const [streamSortRefreshToken, setStreamSortRefreshToken] = useState(0);
  const [timelineFollowNow, setTimelineFollowNow] = useState(true);
  const [manualTimelineWindowEndSec, setManualTimelineWindowEndSec] = useState<number | null>(null);
  const [dashboardManualTimelineWindowEndSec, setDashboardManualTimelineWindowEndSec] = useState<number | null>(null);
  const [selectedTimeSec, setSelectedTimeSec] = useState<number | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<EventLogItem | null>(null);
  const [paused, setPaused] = useState(false);
  const [menuExpanded, setMenuExpanded] = useState(true);
  const [appConfigLoaded, setAppConfigLoaded] = useState(false);
  const [appConfig, setAppConfig] = useState<AppConfig>({ lostRetentionSec: 30, historyWindowSec: 300, staleAfterSec: 5, diagnosticLog: false, dashboardLayoutEditMode: 0 });
  const [maintenanceRefreshToken, setMaintenanceRefreshToken] = useState(0);

  const [dashboardLayouts, setDashboardLayouts] = useState<DashboardLayout[]>([DEFAULT_DASHBOARD_LAYOUT]);
  const [dashboardLayoutId, setDashboardLayoutId] = useState(DEFAULT_DASHBOARD_LAYOUT.id);
  const [dashboardSaveState, setDashboardSaveState] = useState<"idle" | "saving" | "saved" | "error">("idle");
  const [dashboardEditing, setDashboardEditing] = useState(false);
  const [dashboardSelection, setDashboardSelection] = useState<DashboardSelection>(null);
            type="button"
            className={`dashboard-action-button dashboard-time-sync-toggle ${dashboardTimeSyncEnabled ? "primary" : ""}`}
            onClick={() => setDashboardTimeSyncEnabled((enabled) => !enabled)}
            aria-pressed={dashboardTimeSyncEnabled}
            title={dashboardTimeSyncEnabled ? "Events and Timeline clicks sync the Dashboard time" : "Enable time synchronization for Events and Timeline clicks"}
          >
            Time sync: {dashboardTimeSyncEnabled ? "On" : "Off"}
          </button>
          <label className="detail-range-select">
            <span>{t("dashboard.layout")}</span>
            <select value={dashboardLayout.id} onChange={(event) => setDashboardLayoutId(event.target.value)}>
              {dashboardLayouts.map((layout) => <option key={layout.id} value={layout.id}>{layout.nameKey ? t(layout.nameKey) : layout.name}</option>)}
            </select>
          </label>
          <button type="button" className={`dashboard-action-button button-with-icon ${dashboardEditing ? "primary" : ""}`} onClick={() => setDashboardEditing((editing) => !editing)}>
            {dashboardEditing ? <><Icon name="done" size={15} />{t("dashboard.done")}</> : <><Icon name="edit" size={15} />{t("dashboard.editLayout")}</>}
          </button>
          {dashboardEditing && <>
            <button type="button" className="dashboard-action-button button-with-icon" onClick={addDashboardCell}><Icon name="add" size={15} />{t("dashboard.addCell")}</button>
            <button type="button" className="dashboard-action-button button-with-icon" onClick={resetDashboardLayout}><Icon name="reset" size={15} />{t("dashboard.reset")}</button>
            <button type="button" className="dashboard-action-button button-with-icon primary" onClick={() => void saveDashboardLayout()} disabled={dashboardSaveState === "saving"}>
              <Icon name={dashboardSaveState === "saved" ? "done" : "save"} size={15} />{dashboardSaveState === "saving" ? "Saving" : dashboardSaveState === "saved" ? "Saved" : dashboardSaveState === "error" ? "Retry save" : "Save"}
            </button>
          </>}
        </div>}
      />
      <div className="dashboard-pane-body">
        <DashboardGrid
          dashboard={dashboardLayout}
          editing={dashboardEditing}
          editMode={appConfig.dashboardLayoutEditMode}
          renderCell={renderDashboardCellContent}
          renderCellActions={renderDashboardCellActions}
          onLayoutsChange={updateDashboardLayouts}
          onUpdateCell={updateDashboardCell}
          onRemoveCell={removeDashboardCell}
        />
      </div>
      <InspectorTargetDrawer
        open={dashboardTargetPicker !== null}
        streams={streams}
        interfaces={interfaces}
        selectedStreamKey={dashboardSelectedStreamKey}
        selectedFlowKey={dashboardSelectedFlowKey}
        onClose={() => setDashboardTargetPicker(null)}
        onSelectStream={(streamKey) => {
          if (dashboardTargetPicker?.mode === "pinned") updateDashboardCellParams(dashboardTargetPicker.cellId, { detailTargetMode: "pinned", targetStreamKey: streamKey, targetFlowKey: "" });
          else selectDashboardStream(streamKey);
          setDashboardTargetPicker(null);
        }}
        onSelectFlow={(streamKey, flowKey) => {
          if (dashboardTargetPicker?.mode === "pinned") updateDashboardCellParams(dashboardTargetPicker.cellId, { detailTargetMode: "pinned", targetStreamKey: streamKey, targetFlowKey: flowKey });
          else selectDashboardFlow(streamKey, flowKey);
          setDashboardTargetPicker(null);
        }}
      />
            ) : (
              <DetailPane
                stream={detailStreamForStandalone}
                metrics={selectedMetrics}
                selectedFlowKey={selectedFlowKey}
                metricsRange={metricsRange}
                onChangeMetricsRange={setMetricsRange}
                mode={detailMode}
                onChangeMode={setDetailMode}
                onMinimizeWidth={() => undefined}
                onRestoreWidth={() => undefined}
                onMaximizeWidth={() => undefined}
                isWidthMinimized={false}
                isWidthRestored
                isWidthMaximized
                showWidthControls={false}
                onOpenTargetPicker={() => setInspectorTargetPickerOpen(true)}
              />
            )}
          </section>
        )}
      <InspectorTargetDrawer
        open={inspectorTargetPickerOpen}
        streams={streams}
        interfaces={interfaces}
        selectedStreamKey={selectedStreamKey}
        selectedFlowKey={selectedFlowKey}
        onClose={() => setInspectorTargetPickerOpen(false)}
        onSelectStream={(streamKey) => {
          selectInspectorStream(streamKey);
        }}
        onSelectFlow={(streamKey, flowKey) => {
          selectInspectorFlow(streamKey, flowKey);
        }}
      />
      </main>
    );
  }

  return (
    <main className="app-shell" aria-busy={loading}>
      {loading && (
        <div className="loading-overlay" role="status" aria-live="polite" aria-label="Loading">
          <div className="loading-card">
            <span className="loading-label">{t("common.loading")}</span>
                  header={<PaneHeader title={t("nav.information")} icon="information" meta={t("nav.informationHint")} />}
                >
                  <iframe className="external-page-frame" title={t("nav.information")} src="/external-pages/information/" />
                </PaneFrame>
              )}
