import { useEffect, useRef } from "react";
import uPlot from "uplot";
import type { TimeSeriesMetric } from "../types/api";
import { formatNumber } from "./format";

type MetricChartProps = {
  title: string;
  metric?: TimeSeriesMetric;
  height?: number;
  color?: string;
  compact?: boolean;
  fillHeight?: boolean;
};

const syncKey = "stream-detail";

export function MetricChart({ title, metric, height = 190, color = "var(--chart-accent)", compact = false, fillHeight = false }: MetricChartProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<uPlot | null>(null);
  const hasData = Boolean(metric && metric.points.length > 0);
  const hasRangeBand = Boolean(metric && metric.points.some((point) => point.min != null && point.max != null && Math.abs(point.max - point.min) > Number.EPSILON));
  const theme = document.documentElement.dataset.theme ?? "light";

  useEffect(() => {
    if (!hostRef.current || !metric || metric.points.length === 0) return;

    const styles = getComputedStyle(hostRef.current);
    const lineColor = resolveColor(hostRef.current, color, cssVar(styles, "--chart-accent", cssVar(styles, "--accent", "currentColor")));
    const axisColor = cssVar(styles, "--chart-axis", cssVar(styles, "--muted", "currentColor"));
    const gridColor = cssVar(styles, "--chart-grid", "transparent");
    const bandFill = toRgba(lineColor, compact ? 0.18 : 0.24);
    const rangeStroke = toRgba(lineColor, compact ? 0.28 : 0.34);
    const transparentStroke = toRgba(lineColor, 0);
    const chartHeight = chartHeightFor(hostRef.current, height, fillHeight);
    const options: uPlot.Options = {
      width: hostRef.current.clientWidth || 640,
      height: chartHeight,
      cursor: { sync: { key: syncKey } },
      scales: { x: { time: true } },
      legend: { show: !compact },
      axes: compact
        ? [
            { show: false },
            { show: false }
          ]
        : [
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor } },
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, values: (_u, values) => values.map((v) => formatNumber(v)) }
          ],
      series: [
        {},
        {
          label: "min",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        {
          label: "max",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        { label: "avg", stroke: lineColor, width: compact ? 1.3 : 2, points: { show: false } }
      ],
      bands: hasRangeBand ? [{ series: [1, 2], fill: bandFill }] : [],
      padding: compact ? [6, 4, 4, 4] : undefined
    } as uPlot.Options;

    chartRef.current?.destroy();
    chartRef.current = new uPlot(options, toUplotData(metric), hostRef.current);

    const resize = () => {
      if (hostRef.current && chartRef.current) {
        chartRef.current.setSize({
          width: Math.max(1, hostRef.current.clientWidth),
          height: chartHeightFor(hostRef.current, height, fillHeight)
        });
      }
    };
    const resizeObserver = new ResizeObserver(() => resize());
    resizeObserver.observe(hostRef.current);
    window.addEventListener("resize", resize);
    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", resize);
      chartRef.current?.destroy();
      chartRef.current = null;
    };
  }, [metric?.key, hasData, hasRangeBand, height, color, compact, fillHeight, theme]);

  useEffect(() => {
    if (!chartRef.current || !metric || metric.points.length === 0) return;
    chartRef.current.setData(toUplotData(metric));
  }, [metric]);

  return (
    <section className={`chart-card ${compact ? "compact-chart" : ""}`}>
      <div className="chart-header">
        <h3>{title}</h3>
        {!compact && <span>{metric?.unit ?? ""}</span>}
      </div>
      <div className={`chart-host ${compact ? "compact-grid-host" : ""}`} ref={hostRef} style={{ minHeight: fillHeight ? 0 : height }} />
      {!hasData && <div className="empty-chart chart-empty-overlay">No data</div>}
    </section>
  );
}

function cssVar(styles: CSSStyleDeclaration, name: string, fallback: string) {
  return styles.getPropertyValue(name).trim() || fallback;
}

function resolveColor(host: HTMLElement, color: string, fallback: string) {
  if (!color.startsWith("var(")) return color;
  const variableName = color.slice(4, -1).trim();
  if (!variableName) return fallback;
  return getComputedStyle(host).getPropertyValue(variableName).trim() || fallback;
}

function chartHeightFor(host: HTMLDivElement, fallback: number, fillHeight: boolean) {
  if (!fillHeight) return fallback;
  return Math.max(32, host.clientHeight || fallback);
}

function toUplotData(metric: TimeSeriesMetric): uPlot.AlignedData {
  const x = metric.points.map((point) => point.time);
  const min = metric.points.map((point) => point.min ?? point.avg ?? point.value ?? null);
  const max = metric.points.map((point) => point.max ?? point.avg ?? point.value ?? null);
  const avg = metric.points.map((point) => point.avg ?? point.value ?? null);
  return [x, min, max, avg] as uPlot.AlignedData;
}

function toRgba(hex: string, alpha: number) {
  const normalized = hex.replace("#", "");
  if (normalized.length !== 6) return hex;
  const r = Number.parseInt(normalized.slice(0, 2), 16);
  const g = Number.parseInt(normalized.slice(2, 4), 16);
  const b = Number.parseInt(normalized.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}
import { useEffect, useMemo, useState, type FormEvent } from "react";
import { getAlertsSettings, saveAlertsSettings } from "../api/client";
import type { AlertMetricDefinition, AlertRule, AlertsDocument, AlertsResponse } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Tab = "all" | "general" | "interface" | "RTP" | "RTMP" | "SRT" | "HLS";
type PaneState = "loading" | "idle" | "saving" | "saved" | "error";

const tabs: Array<{ key: Tab; label: string }> = [
  { key: "all", label: "All" },
  { key: "general", label: "General" },
  { key: "interface", label: "Interface" },
  { key: "RTP", label: "RTP" },
  { key: "RTMP", label: "RTMP" },
  { key: "SRT", label: "SRT" },
  { key: "HLS", label: "HLS" }
];
const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertsPane() {
  const [settings, setSettings] = useState<AlertsResponse | null>(null);
  const [rows, setRows] = useState<AlertRule[]>([]);
  const [tab, setTab] = useState<Tab>("all");
  const [metricQuery, setMetricQuery] = useState("");
  const [state, setState] = useState<PaneState>("loading");
  const [message, setMessage] = useState("");

  const load = () => {
    setState("loading");
    void getAlertsSettings().then((next) => {
      setSettings(next);
      setRows(next.document.alerts);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load alerts settings");
    });
  };
  useEffect(load, []);

  const visibleRows = useMemo(() => rows.map((row, index) => ({ row, index })).filter(({ row }) => (tab === "all" || ruleTab(row) === tab) && matchesRuleMetric(row, settings?.metrics ?? [], metricQuery)), [rows, settings, tab, metricQuery]);
  const updateRow = (index: number, patch: Partial<AlertRule>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => { if (tab !== "all") setRows((current) => [...current, newRule(tab, current)]); };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving");
    setMessage("");
    const document: AlertsDocument = { ...(settings.document._note ? { _note: settings.document._note } : {}), alerts: rows };
    void saveAlertsSettings(settings.revision, document).then((next) => {
      setSettings(next);
      setRows(next.document.alerts);
      setState("saved");
      setMessage("Saved. Restart STM to apply the new alert rules.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to apply alerts settings");
    });
  };

  return <PaneFrame className="maintenance-frame alerts-frame" header={<PaneHeader title="Alert rules" icon="alertRules" meta="STM thresholds and counter changes" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form" onSubmit={submit}>
      <div className="maintenance-intro">Rules are grouped by protocol. Metric candidates are filtered by the selected target and protocol; Apply writes <code>{settings?.path ?? "the configured alerts file"}</code>. Restart STM before the changes take effect.</div>
      <section className="maintenance-section alerts-toolbar">
        <div className="alerts-tabs" role="tablist" aria-label="Alert rule protocol">
          {tabs.map((item) => <button key={item.key} type="button" role="tab" aria-selected={tab === item.key} className={"alerts-tab" + (tab === item.key ? " is-active" : "")} onClick={() => setTab(item.key)}>{item.label}<span>{item.key === "all" ? rows.length : rows.filter((row) => ruleTab(row) === item.key).length}</span></button>)}
        </div>
        <label className="alerts-metric-search">Find metrics<input type="search" value={metricQuery} onChange={(event) => setMetricQuery(event.target.value)} placeholder="bitrate, rtt, packet…" /></label>
      </section>
      {tab === "HLS" && <div className="protocol-map-notice">HLS candidates are preview-only. They are shown to confirm the future UI and are not emitted or evaluated by STM yet.</div>}
