export function normalizeMetricSampleRecord(record: AnyRecord): NormalizedMetricSample | undefined {
  if (record?.record_type !== "metric_sample" || Number(record?.schema_version) !== 3) return undefined;
  const time = Number(record.time ?? 0);
  const resolutionSec = Number(record.resolution_sec ?? 0);
  const target = isRecord(record.target) ? record.target : undefined;
  const payload = isRecord(record.metrics) ? record.metrics : undefined;
  const targetKey = typeof target?.key === "string" ? target.key : "";
  if (!target || !payload || !targetKey || !Number.isFinite(time) || !Number.isFinite(resolutionSec) || resolutionSec < 1) return undefined;

  const entry = samplePayload(payload, target);
  if (target.kind === "interface") {
    return {
      time,
      targetKey,
      resolutionSec,
      interface: normalizeInterfaceEntry(entry, 0, time)
    };
  }

  const metric = normalizeMetricEntry(entry, time);
  return metric ? { time, targetKey, resolutionSec, metric } : undefined;
}

function samplePayload(payload: AnyRecord, target: AnyRecord): AnyRecord {
  const entry: AnyRecord = { ...payload };
  if (target.kind === "interface") {
    if (target.interface_id !== undefined) entry.interface_id = target.interface_id;
    if (target.interface_name !== undefined) entry.name = target.interface_name;
    if (target.link !== undefined) entry.link = target.link;
  } else {
    if (target.stream_key !== undefined) entry.stream_key = target.stream_key;
    if (target.flow_key !== undefined) entry.flow_key = target.flow_key;
    if (target.proto !== undefined) entry.proto = target.proto;
    if (target.role !== undefined) entry.role = target.role;
    if (target.endpoint !== undefined) entry.endpoint = target.endpoint;
    if (target.interface_id !== undefined) entry.interface_id = target.interface_id;
    if (target.interface_name !== undefined) entry.interface_name = target.interface_name;
