          ].filter((item): item is { key: string; label: string; metric: TimeSeriesMetric } => Boolean(item));

          return (
            <GraphFlowCard
              key={flow.flowKey}
              flow={flow}
              metrics={flowMetrics}
              charts={charts}
              alertRules={alertRules}
              proto={stream.proto}
            />
          );
        })}
      </section>
    </div>
  );
}

