import { useEffect, useMemo, useRef, useState } from "react";
import uPlot from "uplot";
import type { AlertRule, MetricPoint, TimeSeriesMetric } from "../types/api";
import { formatNumber } from "./format";

type MetricChartProps = {
  title: string;
  metric?: TimeSeriesMetric;
  height?: number;
  color?: string;
  compact?: boolean;
  fillHeight?: boolean;
  alertContext?: ChartAlertContext;
};

export type ChartAlertContext = {
  rules: AlertRule[];
  target: "flow" | "interface";
  proto?: string;
};

type ChartThreshold = {
  id: string;
  label: string;
  value: number;
  severity: string;
  recovery: boolean;
};

type TooltipState = {
  left: number;
  top: number;
  point: MetricPoint;
};

const syncKey = "stream-detail";
const chartMetricValueFields = new Set(["value", "bps", "pps", "seconds", "avg", "min", "max", "window", "total"]);

export function MetricChart({ title, metric, height = 190, color = "var(--chart-accent)", compact = false, fillHeight = false, alertContext }: MetricChartProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<uPlot | null>(null);
  const tooltipRef = useRef<HTMLDivElement | null>(null);
  const pointerInsideRef = useRef(false);
  const [tooltip, setTooltip] = useState<TooltipState | null>(null);
  const hasData = Boolean(metric && metric.points.length > 0);
  const hasRangeBand = Boolean(metric && metric.points.some((point) => point.min != null && point.max != null && Math.abs(point.max - point.min) > Number.EPSILON));
  const thresholds = useMemo(() => thresholdsForMetric(metric, alertContext), [metric, alertContext]);
  const thresholdSignature = thresholds.map((threshold) => [threshold.id, threshold.value, threshold.severity, threshold.recovery].join(":" )).join("|");
  const theme = document.documentElement.dataset.theme ?? "light";

  useEffect(() => {
    if (!hostRef.current || !metric || metric.points.length === 0) return;

    const styles = getComputedStyle(hostRef.current);
    const lineColor = resolveColor(hostRef.current, color, cssVar(styles, "--chart-accent", cssVar(styles, "--accent", "currentColor")));
    const axisColor = cssVar(styles, "--chart-axis", cssVar(styles, "--muted", "currentColor"));
    const gridColor = cssVar(styles, "--chart-grid", "transparent");
    const bandFill = toRgba(lineColor, compact ? 0.18 : 0.24);
    const rangeStroke = toRgba(lineColor, compact ? 0.28 : 0.34);
    const transparentStroke = toRgba(lineColor, 0);
    const chartHeight = chartHeightFor(hostRef.current, height, fillHeight);
    const thresholdSeries = thresholds.map((threshold) => ({
      label: threshold.label,
      stroke: resolveColor(hostRef.current!, thresholdColor(threshold.severity), lineColor),
      width: threshold.recovery ? 1 : 1.5,
      dash: threshold.recovery ? [5, 4] : undefined,
      points: { show: false }
    }));
    const options: uPlot.Options = {
      width: hostRef.current.clientWidth || 640,
      height: chartHeight,
      cursor: { sync: { key: syncKey } },
      scales: { x: { time: true } },
      legend: { show: false },
      hooks: {
        setCursor: [(chart) => {
          if (!pointerInsideRef.current || chart.cursor.idx == null || !hostRef.current) return;
          const point = metric.points[chart.cursor.idx];
          if (!point) return;
          const cursorLeft = chart.cursor.left ?? 0;
          const cursorTop = chart.cursor.top ?? 0;
          setTooltip({
            left: Math.min(Math.max(4, cursorLeft + 12), Math.max(4, hostRef.current.clientWidth - 176)),
            top: Math.min(Math.max(4, cursorTop + 12), Math.max(4, hostRef.current.clientHeight - 96)),
            point
          });
        }]
      },
      axes: compact
        ? [
            { show: false },
            { show: false }
          ]
        : [
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor } },
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, values: (_u, values) => values.map((v) => formatNumber(v)) }
          ],
      series: [
        {},
        {
          label: "min",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        {
          label: "max",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        { label: "avg", stroke: lineColor, width: compact ? 1.3 : 2, points: { show: false } },
        ...thresholdSeries
      ],
      bands: hasRangeBand ? [{ series: [2, 1], fill: bandFill }] : [],
      padding: compact ? [6, 4, 4, 4] : undefined
    } as uPlot.Options;

    chartRef.current?.destroy();
    chartRef.current = new uPlot(options, toUplotData(metric, thresholds), hostRef.current);

    const resize = () => {
      if (hostRef.current && chartRef.current) {
        chartRef.current.setSize({
          width: Math.max(1, hostRef.current.clientWidth),
          height: chartHeightFor(hostRef.current, height, fillHeight)
        });
      }
    };
    const resizeObserver = new ResizeObserver(() => resize());
    resizeObserver.observe(hostRef.current);
    window.addEventListener("resize", resize);
    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", resize);
      chartRef.current?.destroy();
      chartRef.current = null;
    };
  }, [metric?.key, hasData, hasRangeBand, height, color, compact, fillHeight, thresholdSignature, theme]);

  useEffect(() => {
    if (!chartRef.current || !metric || metric.points.length === 0) return;
    chartRef.current.setData(toUplotData(metric, thresholds));
  }, [metric, thresholdSignature]);

  return (
    <section className={`chart-card ${compact ? "compact-chart" : ""}`}>
      <div className="chart-header">
        <h3>{title}</h3>
        {!compact && <span>{metric?.unit ?? ""}</span>}
      </div>
      <div
        className={`chart-host ${compact ? "compact-grid-host" : ""}`}
        ref={hostRef}
        style={{ minHeight: fillHeight ? 0 : height }}
        onPointerEnter={() => { pointerInsideRef.current = true; }}
        onPointerLeave={() => { pointerInsideRef.current = false; setTooltip(null); }}
      >
        {tooltip && <div ref={tooltipRef} className="chart-tooltip" aria-hidden="true" style={{ left: tooltip.left, top: tooltip.top }}>
          <strong>{formatChartTime(tooltip.point.time)}</strong>
          <span>min <b>{formatChartValue(tooltip.point.min ?? tooltip.point.avg ?? tooltip.point.value, metric?.unit)}</b></span>
          <span>avg <b>{formatChartValue(tooltip.point.avg ?? tooltip.point.value, metric?.unit)}</b></span>
          <span>max <b>{formatChartValue(tooltip.point.max ?? tooltip.point.avg ?? tooltip.point.value, metric?.unit)}</b></span>
        </div>}
      </div>
      {!hasData && <div className="empty-chart chart-empty-overlay">No data</div>}
    </section>
  );
}

function thresholdsForMetric(metric: TimeSeriesMetric | undefined, context: ChartAlertContext | undefined): ChartThreshold[] {
  if (!metric || !context) return [];
  return context.rules.flatMap((rule) => {
    if (rule.enabled === false || (rule.type ?? "threshold") !== "threshold") return [];
    const target = rule.target ?? "any";
    if (target !== "any" && target !== context.target) return [];
    if (context.proto && rule.proto && rule.proto !== context.proto) return [];
    if (metricKeyForAlert(rule.metric) !== metric.key || !Number.isFinite(rule.error_threshold)) return [];
    const severity = rule.severity ?? "warning";
    const result: ChartThreshold[] = [{ id: rule.id, label: `${rule.id} trigger`, value: rule.error_threshold!, severity, recovery: false }];
    if (Number.isFinite(rule.recover_threshold) && Math.abs(rule.recover_threshold! - rule.error_threshold!) > Number.EPSILON) {
      result.push({ id: `${rule.id}:recovery`, label: `${rule.id} recovery`, value: rule.recover_threshold!, severity, recovery: true });
    }
    return result;
  });
}

function metricKeyForAlert(key: string) {
  const parts = key.split(".");
  return chartMetricValueFields.has(parts.at(-1) ?? "") ? parts.slice(0, -1).join(".") : key;
}

function thresholdColor(severity: string) {
  if (severity === "critical" || severity === "error") return "var(--error)";
  if (severity === "warning") return "var(--warning)";
  return "var(--accent)";
}

function formatChartTime(time: number) {
  return new Intl.DateTimeFormat(undefined, { hour: "2-digit", minute: "2-digit", second: "2-digit" }).format(new Date(time * 1000));
}

function formatChartValue(value: number | undefined, unit: string | undefined) {
  return value === undefined ? "–" : `${formatNumber(value)}${unit ? ` ${unit}` : ""}`;
}

function cssVar(styles: CSSStyleDeclaration, name: string, fallback: string) {
  return styles.getPropertyValue(name).trim() || fallback;
}

function resolveColor(host: HTMLElement, color: string, fallback: string) {
  if (!color.startsWith("var(")) return color;
  const variableName = color.slice(4, -1).trim();
  if (!variableName) return fallback;
  return getComputedStyle(host).getPropertyValue(variableName).trim() || fallback;
}

function chartHeightFor(host: HTMLDivElement, fallback: number, fillHeight: boolean) {
  if (!fillHeight) return fallback;
  return Math.max(32, host.clientHeight || fallback);
}

function toUplotData(metric: TimeSeriesMetric, thresholds: ChartThreshold[]): uPlot.AlignedData {
  const x = metric.points.map((point) => point.time);
  const min = metric.points.map((point) => point.min ?? point.avg ?? point.value ?? null);
  const max = metric.points.map((point) => point.max ?? point.avg ?? point.value ?? null);
  const avg = metric.points.map((point) => point.avg ?? point.value ?? null);
  const thresholdData = thresholds.map((threshold) => metric.points.map(() => threshold.value));
  return [x, min, max, avg, ...thresholdData] as uPlot.AlignedData;
}

function toRgba(hex: string, alpha: number) {
  const normalized = hex.replace("#", "");
  if (normalized.length !== 6) return hex;
  const r = Number.parseInt(normalized.slice(0, 2), 16);
  const g = Number.parseInt(normalized.slice(2, 4), 16);
  const b = Number.parseInt(normalized.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}
