/* Match Stats heading size with other detail section headings */
.stats-section h3 { font-size: inherit; line-height: normal; margin-bottom: 8px; }
/* Keep chart DOM height stable during realtime updates */
.chart-card { position: relative; overflow-anchor: none; min-width: 0; }
.chart-host { position: relative; width: 100%; min-width: 0; overflow: hidden; }
.chart-tooltip {
  position: fixed;
  z-index: 45;
  display: grid;
  gap: 2px;
  min-width: 132px;
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--surface) 94%, transparent);
  box-shadow: var(--shadow-sm);
  color: var(--text);
  font-size: var(--font-size-xs);
  font-variant-numeric: tabular-nums;
  pointer-events: none;
