			_xDim = rotSrc ? _h : _w,
			_yDim = rotSrc ? _w : _h,
			_xPos = rotSrc ? _t : _l,
		val = s.values(self, sidx, idx) ?? NULL_LEGEND_VALUES;
	else {
		val = s.value(self, idx == null ? null : src[idx], sidx, idx);
		val = val == null ? NULL_LEGEND_VALUES : {_: val};
	}

	legend.values[sidx] = val;
}

