function drawThresholdLabels(chart: uPlot, thresholds: DrawThresholdLabel[], unit: string | undefined, background: string, compact: boolean) {
  if (thresholds.length === 0) return;
  const ratio = uPlot.pxRatio;
  const fontSize = (compact ? 9 : 10) * ratio;
  const labelHeight = (compact ? 13 : 16) * ratio;
  const gap = 3 * ratio;
  const padding = 4 * ratio;
  const { left, top, width, height } = chart.bbox;
  const entries = thresholds
    .map((threshold) => ({
      threshold,
      text: threshold.metric + " " + (threshold.recovery ? "recovery" : threshold.operator) + " " + formatFixedNumber(threshold.value) + (unit ? " " + unit : ""),
      y: chart.valToPos(threshold.value, "y", true)
    }))
    .filter((entry) => entry.y >= top && entry.y <= top + height)
    .sort((a, b) => a.y - b.y);
  if (entries.length === 0) return;

  const minY = top + labelHeight / 2;
  const maxY = top + height - labelHeight / 2;
  let previousY = minY - labelHeight - gap;
  const placed = entries.map((entry) => {
    const y = Math.max(minY, entry.y, previousY + labelHeight + gap);
    previousY = y;
    return { ...entry, y };
  });
  const overflow = placed[placed.length - 1].y - maxY;
  if (overflow > 0) placed.forEach((entry) => { entry.y -= overflow; });

  const context = chart.ctx;
  context.save();
  context.font = fontSize + "px system-ui, -apple-system, BlinkMacSystemFont, sans-serif";
  context.textAlign = "right";
  context.textBaseline = "middle";
  for (const entry of placed) {
    const textWidth = context.measureText(entry.text).width;
    const x = left + width - padding;
    context.fillStyle = background;
    context.fillRect(x - textWidth - padding, entry.y - labelHeight / 2, textWidth + padding * 2, labelHeight);
    context.fillStyle = entry.threshold.color;
    context.fillText(entry.text, x, entry.y);
  }
  context.restore();
}

