import { Responsive, useContainerWidth, horizontalCompactor, noCompactor, verticalCompactor, type Compactor, type Layout, type LayoutItem } from "react-grid-layout";
import { useCallback, useMemo, useState, type ReactNode, type Ref } from "react";
import { Icon, type IconName } from "./ui/Icon";
import { useI18n } from "../i18n";
import type { DashboardBreakpoint, DashboardCell, DashboardLayout, DashboardResponsiveLayouts } from "../types/api";

const fixedGridCompactor: Compactor = {
  ...noCompactor,
  preventCollision: true
};

const pushGridCompactor: Compactor = {
  ...noCompactor,
  preventCollision: false
};

function dashboardGridCompactor(editMode: number): Compactor {
  if (editMode === 1) return verticalCompactor;
  if (editMode === 2) return horizontalCompactor;
  if (editMode === 3) return pushGridCompactor;
  return fixedGridCompactor;
}

const dashboardViewIcons: Record<DashboardCell["viewType"], IconName> = {
  streams: "streams",
  detail: "detail",
  timeline: "timeline",
  topology: "topology",
  events: "events"
};

type DashboardGridProps = {
  dashboard: DashboardLayout;
  editing: boolean;
  editMode: number;
  renderCell: (cell: DashboardCell) => ReactNode;
  renderCellActions?: (cell: DashboardCell, editing: boolean) => ReactNode;
  onLayoutsChange: (layouts: DashboardResponsiveLayouts) => void;
  onUpdateCell: (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => void;
  onRemoveCell: (cellId: string) => void;
};

export function DashboardGrid({
  dashboard,
  editing,
  editMode,
  renderCell,
  renderCellActions,
  onLayoutsChange,
  onUpdateCell,
  onRemoveCell
}: DashboardGridProps) {
  const { t } = useI18n();
  const { width, containerRef, mounted } = useContainerWidth({ initialWidth: 1280 });
  const [activeBreakpoint, setActiveBreakpoint] = useState<DashboardBreakpoint>(breakpointForWidth(width));
  const cellsByBreakpoint = useMemo(() => buildResponsiveCells(dashboard.cells, dashboard.layouts), [dashboard.cells, dashboard.layouts]);
  const activeCells = cellsByBreakpoint[activeBreakpoint] ?? dashboard.cells;
  const layouts = useMemo(() => Object.fromEntries(
    (Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]).map((breakpoint) => [
      breakpoint,
      cellsByBreakpoint[breakpoint].map(toLayoutItem)
    ])
  ) as unknown as Record<DashboardBreakpoint, Layout>, [cellsByBreakpoint]);

  const handleLayoutChange = useCallback((_layout: Layout, nextLayouts: Partial<Record<string, Layout>>) => {
    if (!editing) return;
    const normalized = {} as DashboardResponsiveLayouts;
    for (const breakpoint of Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]) {
      const layout = nextLayouts[breakpoint];
      if (layout) normalized[breakpoint] = mergeLayoutCells(cellsByBreakpoint[breakpoint], layout);
    }
    onLayoutsChange(normalized);
  }, [editing, cellsByBreakpoint, onLayoutsChange]);

  return (
    <div ref={containerRef as unknown as Ref<HTMLDivElement>} className={`dashboard-rgl-shell ${editing ? "is-editing" : "is-viewing"}`}>
      {mounted && (
        <Responsive
          className="dashboard-rgl"
          width={width}
          layouts={layouts}
          breakpoints={BREAKPOINTS}
          cols={BREAKPOINT_COLUMNS}
          rowHeight={dashboard.rowHeight}
          margin={[10, 10]}
          containerPadding={[0, 0]}
          dragConfig={{
            enabled: editing,
            handle: ".dashboard-drag-handle",
            cancel: ".dashboard-cell-body, .dashboard-cell-actions, input, select, .dashboard-cell-remove, a"
          }}
          resizeConfig={{
            enabled: editing,
            handles: ["se"]
          }}
          compactor={dashboardGridCompactor(editMode)}
          autoSize
          onBreakpointChange={(breakpoint) => setActiveBreakpoint(toDashboardBreakpoint(breakpoint))}
          onLayoutChange={handleLayoutChange}
        >
          {activeCells.map((cell) => (
            <section key={cell.id} className={`dashboard-cell dashboard-cell-${cell.viewType}`}>
              <header className="pane-header pane-header-compact dashboard-cell-header">
                {editing ? <>
                  <button type="button" className="dashboard-drag-handle" aria-label={t("dashboard.moveCell")} title={t("dashboard.dragToMove")}><Icon name="drag" size={16} /></button>
                  <input
                    value={cell.title}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, title: event.target.value, titleKey: undefined }))}
                    aria-label={t("dashboard.cellTitle")}
                  />
                  <select
                    value={cell.viewType}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, viewType: event.target.value as DashboardCell["viewType"], title: titleForDashboardView(event.target.value as DashboardCell["viewType"]), titleKey: dashboardViewMessageKey(event.target.value as DashboardCell["viewType"]) }))}
                    aria-label={t("dashboard.cellViewType")}
                  >
                    {DASHBOARD_VIEW_TYPES.map((viewType) => <option key={viewType} value={viewType}>{t(dashboardViewMessageKey(viewType))}</option>)}
                  </select>
                  {renderCellActions && <div className="dashboard-cell-actions dashboard-cell-edit-actions">{renderCellActions(cell, true)}</div>}
                  <button type="button" className="dashboard-cell-remove" onClick={() => onRemoveCell(cell.id)} disabled={activeCells.length <= 1} aria-label={t("dashboard.removeCell")} title={t("dashboard.removeCell")}><Icon name="delete" size={15} /></button>
                </> : <>
                  <Icon className="pane-header-icon" name={dashboardViewIcons[cell.viewType]} size={14} />
                  <strong className="pane-header-title">{cell.titleKey ? t(cell.titleKey) : cell.title}</strong>
                  {renderCellActions && <div className="dashboard-cell-actions">{renderCellActions(cell, false)}</div>}
                </>}
              </header>
              <div className="dashboard-cell-body">
                {renderCell(cell)}
              </div>
            </section>
          ))}
        </Responsive>
      )}
    </div>
  );
}
const BREAKPOINTS: Record<DashboardBreakpoint, number> = { desktop: 1200, tablet: 700, mobile: 0 };
const BREAKPOINT_COLUMNS: Record<DashboardBreakpoint, number> = { desktop: 24, tablet: 12, mobile: 4 };

function breakpointForWidth(width: number): DashboardBreakpoint {
  if (width >= BREAKPOINTS.desktop) return "desktop";
  if (width >= BREAKPOINTS.tablet) return "tablet";
  return "mobile";
}

function toDashboardBreakpoint(breakpoint: string): DashboardBreakpoint {
  return breakpoint === "desktop" || breakpoint === "tablet" || breakpoint === "mobile"
    ? breakpoint
    : "desktop";
}

function toLayoutItem(cell: DashboardCell): LayoutItem {
  return {
    i: cell.id,
    x: cell.grid.x,
    y: cell.grid.y,
    w: cell.grid.w,
    h: cell.grid.h,
    minW: 2,
    maxW: 48,
    minH: 3,
    maxH: 40,
    isBounded: true
  };
}

function buildResponsiveCells(cells: DashboardCell[], saved: DashboardResponsiveLayouts | undefined): Record<DashboardBreakpoint, DashboardCell[]> {
  return {
    desktop: saved?.desktop ?? cells,
    tablet: saved?.tablet ?? fallbackLayout(cells, 12, 2),
    mobile: saved?.mobile ?? fallbackLayout(cells, 4, 1)
  };
}

function fallbackLayout(cells: DashboardCell[], columns: number, columnCount: number) {
  const slotWidth = Math.floor(columns / columnCount);
  const result: DashboardCell[] = [];
  let y = 0;
  for (let index = 0; index < cells.length; index += columnCount) {
    const row = cells.slice(index, index + columnCount);
    const rowHeight = Math.max(...row.map((cell) => cell.grid.h), 3);
    row.forEach((cell, column) => {
      result.push({
        ...cell,
        grid: {
          x: column * slotWidth,
          y,
          w: slotWidth,
          h: cell.grid.h
        }
      });
    });
    y += rowHeight;
  }
  return result;
}

function mergeLayoutCells(cells: DashboardCell[], layout: Layout) {
  const positions = new Map(layout.map((item) => [item.i, item]));
  return cells.map((cell) => {
    const item = positions.get(cell.id);
    return item ? { ...cell, grid: { x: item.x, y: item.y, w: item.w, h: item.h } } : cell;
  });
}

const DASHBOARD_VIEW_TYPES: DashboardCell["viewType"][] = ["streams", "detail", "timeline", "topology", "events"];

function dashboardViewMessageKey(viewType: DashboardCell["viewType"]) {
  return viewType === "detail" ? "nav.inspector" : `nav.${viewType}`;
}

function titleForDashboardView(viewType: DashboardCell["viewType"]) {
  switch (viewType) {
    case "streams": return "Streams";
    case "detail": return "Inspector";
    case "timeline": return "Timeline";
    case "topology": return "Topology";
    case "events": return "Events";
  }
}
export type OverviewStats = {
  gap: number;
  dup: number;
  reorder: number;
  events: number;
  /** False when the selected historical snapshot has no event-journal aggregation. */
  eventsAvailable?: boolean;
};

export type FlowState = {
  flowKey: string;
  role: string;
  label: string;
  active: boolean;
  interfaceId?: number;
  interfaceName?: string;
  endpointSrc?: string;
  endpointDst?: string;
  lastSeen: number;
  metrics: Record<string, NumericStat>;
};

export type StreamState = Omit<StreamListItem, "flows"> & {
  flows: FlowState[];
};

export type MetricDescriptor = {
  key: string;
  label: string;
  unit?: string;
  category: "primary" | "secondary" | "stat";
  display: "range-line" | "line" | "stat";
  priority: number;
};

export type InterfaceCounters = {
  bytes: NumericStat;
  packets: NumericStat;
  errors: NumericStat;
  dropped: NumericStat;
};

export type InterfaceLinkInfo = {
  speedMbps?: number;
  duplex?: string;
  operstate?: string;
  carrier?: boolean;
  mtu?: number;
  mac?: string;
};

export type InterfaceRateInfo = {
  bitrateBps?: number;
  utilization?: number;
  headroomBps?: number;
};

export type InterfaceListItem = {
  key: string;
  interfaceId?: number;
  name: string;
  observed: boolean;
  available: boolean;
  link?: InterfaceLinkInfo;
  lastSeen?: number;
  rx: InterfaceCounters;
  tx: InterfaceCounters;
  rxRate?: InterfaceRateInfo;
  txRate?: InterfaceRateInfo;
  rxBitrate: NumericStat;
  txBitrate: NumericStat;
  rxSparkline: number[];
  txSparkline: number[];
  streamCount: number;
};

export type InterfaceMetricsResponse = {
  key: string;
  interfaceId?: number;
  name: string;
  windowSec: number;
  metrics: Record<string, TimeSeriesMetric>;
};

export type TimeSeriesMetric = {
  key: string;
  label: string;
  unit?: string;
  points: MetricPoint[];
};

export type FlowMetricsResponse = {
  flowKey: string;
  role: string;
  label: string;
  endpointSrc?: string;
  endpointDst?: string;
  metrics: Record<string, TimeSeriesMetric>;
};

export type StreamMetricsResponse = {
  streamKey: string;
  windowSec: number;
  streamBitrate: TimeSeriesMetric;
  flows: FlowMetricsResponse[];
  descriptors: MetricDescriptor[];
};

export type EventLogItem = {
  id: string;
  time: number;
  type: string;
  level: "info" | "warn" | "error";
  scope: "system" | "stream" | "flow";
  proto?: string;
  interfaceId?: number;
  streamKey?: string;
  flowKey?: string;
  targetLabel?: string;
  message: string;
  detail?: unknown;
import type { AppConfig, MaintenanceSettingsResponse, ProtocolMapDocument, ProtocolMapResponse, AlertsDocument, AlertsResponse, BootstrapResponse, EventLogItem, InterfaceListItem, InterfaceMetricsResponse, StreamListItem, StreamMetricsResponse, StreamState, Summary, TimelineViewResponse, DashboardLayout, StreamsSnapshotResponse, TopologyRelationFlowsResponse, TopologySnapshot, LiveStatus } from "../types/api";

export type MetricsRangeQuery = {
  windowSec?: number;
  from?: number;
  to?: number;
  resolutionSec?: number;
};

export type TimelineRangeQuery = {
  from?: number;
  to?: number;
  includeFlows?: boolean;
};

export async function getDashboardLayouts(): Promise<DashboardLayout[]> {
  return getJson("/api/dashboard-layouts");
}

export async function saveDashboardLayouts(layouts: DashboardLayout[]): Promise<DashboardLayout[]> {
  const response = await fetch("/api/dashboard-layouts", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(layouts)
  });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
  return response.json() as Promise<DashboardLayout[]>;
}

export async function getStreams(): Promise<StreamListItem[]> {
  return getJson("/api/streams");
}

export async function getStreamsSnapshotAt(timeSec: number, eventRange?: { from: number; to: number }): Promise<StreamsSnapshotResponse> {
  const query = new URLSearchParams({ time: String(timeSec) });
  if (eventRange) {
    query.set("overviewEventFrom", String(eventRange.from));
    query.set("overviewEventTo", String(eventRange.to));
  }
  return getJson("/api/streams?" + query.toString());
}

export async function getAppConfig(): Promise<AppConfig> {
  return getJson("/api/config");
}


export async function getLiveStatus(): Promise<LiveStatus> {
  return getJson("/api/live");
}
export async function getMaintenanceSettings(): Promise<MaintenanceSettingsResponse> {
  return getJson("/api/maintenance/frontend-settings");
}

export async function saveMaintenanceSettings(revision: number, values: AppConfig): Promise<MaintenanceSettingsResponse> {
  const response = await fetch("/api/maintenance/frontend-settings", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ revision, values })
  });
  if (!response.ok) {
    const body = await response.json().catch(() => undefined) as { error?: string } | undefined;
    throw new Error(body?.error ?? "Request failed");
  }
  return response.json() as Promise<MaintenanceSettingsResponse>;
}

export async function getAlertsSettings(): Promise<AlertsResponse> {
  const response = await fetch("/api/maintenance/alerts");
  if (!response.ok) { const body = await response.json().catch(() => undefined) as { error?: string } | undefined; throw new Error(body?.error ?? response.status + " " + response.statusText); }
  return response.json() as Promise<AlertsResponse>;
}

export async function saveAlertsSettings(revision: string, document: AlertsDocument): Promise<AlertsResponse> {
  const response = await fetch("/api/maintenance/alerts", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ revision, document }) });
  if (!response.ok) { const body = await response.json().catch(() => undefined) as { error?: string } | undefined; throw new Error(body?.error ?? "Request failed"); }
  return response.json() as Promise<AlertsResponse>;
}

export async function getProtocolMapSettings(): Promise<ProtocolMapResponse> {
  const response = await fetch("/api/maintenance/protocol-map");
  if (!response.ok) {
    const body = await response.json().catch(() => undefined) as { error?: string } | undefined;
    throw new Error(body?.error ?? response.status + " " + response.statusText);
  }
  return response.json() as Promise<ProtocolMapResponse>;
}

export async function saveProtocolMapSettings(revision: string, path: string, document: ProtocolMapDocument): Promise<ProtocolMapResponse> {
  const response = await fetch("/api/maintenance/protocol-map", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ revision, path, document }) });
  if (!response.ok) { const body = await response.json().catch(() => undefined) as { error?: string } | undefined; throw new Error(body?.error ?? "Request failed"); }
  return response.json() as Promise<ProtocolMapResponse>;
}

export async function getBootstrap(): Promise<BootstrapResponse> {
  return getJson("/api/bootstrap");
}

export async function getTopology(timeSec?: number): Promise<TopologySnapshot> {
  const suffix = timeSec !== undefined ? `?time=${encodeURIComponent(String(timeSec))}` : "";
  return getJson(`/api/topology${suffix}`);
}

export async function getTopologyRelationFlows(relationId: string, includeStale = false): Promise<TopologyRelationFlowsResponse> {
  const query = new URLSearchParams({ relation: relationId, state: includeStale ? "all" : "active", limit: "50" });
  return getJson(`/api/topology/flows?${query.toString()}`);
}

export async function getTimeline(query: TimelineRangeQuery = {}): Promise<TimelineViewResponse> {
  const params = new URLSearchParams();
  if (query.from !== undefined) params.set("from", String(query.from));
  if (query.to !== undefined) params.set("to", String(query.to));
  if (query.includeFlows !== undefined) params.set("includeFlows", query.includeFlows ? "1" : "0");
  const suffix = params.toString() ? `?${params.toString()}` : "";
  return getJson(`/api/timeline${suffix}`);
}

export async function getInterfaces(): Promise<InterfaceListItem[]> {
  return getJson("/api/interfaces");
}

export async function getInterfaceMetrics(interfaceId: number, windowSec = 300): Promise<InterfaceMetricsResponse> {
  return getJson(`/api/interfaces/${interfaceId}/metrics?windowSec=${windowSec}`);
}

export async function getInterfaceMetricsByKey(key: string, query: number | MetricsRangeQuery = 300): Promise<InterfaceMetricsResponse> {
  const params = new URLSearchParams();
  if (typeof query === "number") params.set("windowSec", String(query));
  else {
    if (query.windowSec !== undefined) params.set("windowSec", String(query.windowSec));
    if (query.from !== undefined) params.set("from", String(query.from));
    if (query.to !== undefined) params.set("to", String(query.to));
  }
  return getJson(`/api/interfaces/by-key/${encodeURIComponent(key)}/metrics?${params.toString()}`);
}

export async function getSummary(): Promise<Summary> {
  return getJson("/api/summary");
}

export async function getStream(streamKey: string): Promise<StreamState> {
  return getJson(`/api/streams/${encodeURIComponent(streamKey)}`);
}

export async function getStreamMetrics(streamKey: string, query: number | MetricsRangeQuery = 300): Promise<StreamMetricsResponse> {
  const params = new URLSearchParams();
  if (typeof query === "number") {
    params.set("windowSec", String(query));
  } else {
    if (query.windowSec !== undefined) params.set("windowSec", String(query.windowSec));
    if (query.from !== undefined) params.set("from", String(query.from));
    if (query.to !== undefined) params.set("to", String(query.to));
    if (query.resolutionSec !== undefined) params.set("resolutionSec", String(query.resolutionSec));
  }
  return getJson(`/api/streams/${encodeURIComponent(streamKey)}/metrics?${params.toString()}`);
}

export async function getEvents(params: {
  streamKey?: string;
  flowKey?: string;
  interfaceId?: number;
  limit?: number;
  from?: number;
  to?: number;
  proto?: string;
  level?: "info" | "warn" | "error";
  type?: string;
} = {}): Promise<EventLogItem[]> {
  const query = new URLSearchParams();
  if (params.streamKey) query.set("streamKey", params.streamKey);
  if (params.flowKey) query.set("flowKey", params.flowKey);
  if (params.interfaceId !== undefined) query.set("interfaceId", String(params.interfaceId));
  if (params.from !== undefined) query.set("from", String(params.from));
  if (params.to !== undefined) query.set("to", String(params.to));
  if (params.proto) query.set("proto", params.proto);
  if (params.level) query.set("level", params.level);
  if (params.type) query.set("type", params.type);
  if (params.limit) query.set("limit", String(params.limit));
  const suffix = query.toString() ? `?${query.toString()}` : "";
  return getJson(`/api/events${suffix}`);
}

async function getJson<T>(url: string): Promise<T> {
  const response = await fetch(url, { cache: "no-store" });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
  return response.json() as Promise<T>;
}
