}

function InterfaceOverview({ item, metrics, alertContext }: { item: InterfaceListItem; metrics: InterfaceMetricsResponse | null; alertContext: ChartAlertContext }) {
  return (
    <div className="graph-mode-layout interface-overview-layout">
      <section className="graph-summary-band">
        <Stat label="RX" value={formatBitrate(item.rxBitrate.value ?? item.rxBitrate.avg)} />
        <Stat label="TX" value={formatBitrate(item.txBitrate.value ?? item.txBitrate.avg)} />
        <Stat label="Headroom" value={formatPercent(interfaceHeadroom(item))} />
        <Stat label="Link" value={formatLinkSummary(item)} />
        <Stat label="Drops" value={formatNumber((item.rx.dropped.value ?? 0) + (item.tx.dropped.value ?? 0))} />
        <Stat label="Errors" value={formatNumber((item.rx.errors.value ?? 0) + (item.tx.errors.value ?? 0))} />
      </section>
      <BandwidthUsagePanel item={item} compact />
      <section className="graph-card-grid interface-overview-grid">
        <MetricChart title="RX Utilization" metric={metrics?.metrics["rx.utilization"]} height={108} compact color="var(--chart-rx)" alertContext={alertContext} />
        <MetricChart title="TX Utilization" metric={metrics?.metrics["tx.utilization"]} height={108} compact color="var(--chart-tx)" alertContext={alertContext} />
        <MetricChart title="RX Bitrate" metric={metrics?.metrics["rx.bitrate"]} height={126} compact color="var(--chart-rx)" alertContext={alertContext} />
        <MetricChart title="TX Bitrate" metric={metrics?.metrics["tx.bitrate"]} height={126} compact color="var(--chart-tx)" alertContext={alertContext} />
        <MetricChart title="RX Packets" metric={metrics?.metrics["rx.packets"]} height={108} compact color="var(--chart-rx-packets)" alertContext={alertContext} />
        <MetricChart title="TX Packets" metric={metrics?.metrics["tx.packets"]} height={108} compact color="var(--chart-tx-packets)" alertContext={alertContext} />
        <MetricChart title="RX Dropped" metric={metrics?.metrics["rx.dropped"]} height={108} compact color="var(--chart-rx-dropped)" alertContext={alertContext} />
        <MetricChart title="TX Dropped" metric={metrics?.metrics["tx.dropped"]} height={108} compact color="var(--chart-tx-dropped)" alertContext={alertContext} />
        <MetricChart title="RX Errors" metric={metrics?.metrics["rx.errors"]} height={108} compact color="var(--chart-rx-errors)" alertContext={alertContext} />
