  border-color: var(--accent-border);
}

.dashboard-rgl-shell.is-editing .react-grid-item.react-draggable-dragging .dashboard-cell {
  box-shadow: var(--shadow-md);
}

.dashboard-rgl-shell.is-editing .react-resizable-handle::after {
  border-color: var(--accent);
}

.dashboard-stream-focus-hidden {
  min-height: 24px;
  padding: 0 7px;
  border-color: var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 10px;
  white-space: nowrap;
}

.dashboard-topology-selection-close {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--muted);
}

.dashboard-topology-selection-close:hover,
.dashboard-topology-selection-close:focus-visible {
  background: var(--accent-soft);
  color: var(--accent);
  outline: none;
}

.dashboard-topology-focus-status {
  position: absolute;
  z-index: 12;
  top: 10px;
  left: 10px;
  max-width: calc(100% - 20px);
  padding: 5px 7px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--surface) 94%, var(--surface-muted));
  color: var(--muted);
  font-size: 10px;
}

@media (max-width: 720px) {
  .dashboard-toolbar .pane-header-meta,
  .dashboard-toolbar .detail-range-select {
    display: none;
  }

  .dashboard-cell-search {
    width: min(140px, 36vw);
  }

