perl -0pi -e 's#\A#import type { CSSProperties } from "react";
import type { AlertRule, InspectorCell, InterfaceListItem, InterfaceMetricsResponse, MetricDescriptor, StreamMetricsResponse, StreamState, TimeSeriesMetric } from "../types/api";
import { formatBitrate, formatMetricValue, metricDisplayScale } from "./format";
import { MetricChart, type ChartAlertContext, type ChartYScale } from "./MetricChart";

type InspectorCellsProps = {
  cell: InspectorCell;
  stream: StreamState | null;
  metrics: StreamMetricsResponse | null;
  selectedFlowKey: string | null;
  interfaceItem: InterfaceListItem | null;
  interfaceMetrics: InterfaceMetricsResponse | null;
  alertRules: AlertRule[];
};

export function InspectorCellContent({ cell, stream, metrics, selectedFlowKey, interfaceItem, interfaceMetrics, alertRules }: InspectorCellsProps) {
  const selectedFlows = stream ? (selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows) : [];
  const visibleMetrics = metrics && selectedFlowKey ? { ...metrics, flows: metrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) } : metrics;
  const chartYScale = yScaleForCell(cell);
  const flowAlertContext: ChartAlertContext | undefined = stream ? { rules: alertRules, target: "flow", proto: stream.proto } : undefined;
  const interfaceAlertContext: ChartAlertContext | undefined = interfaceItem ? { rules: alertRules, target: "interface" } : undefined;

  if (cell.type === "summary") {
    if (interfaceItem && !stream) return <SummaryGrid items={[
      ["RX", formatBitrate(interfaceItem.rxBitrate.value ?? interfaceItem.rxBitrate.avg)],
      ["TX", formatBitrate(interfaceItem.txBitrate.value ?? interfaceItem.txBitrate.avg)],
      ["Link", interfaceItem.link?.speedMbps ? String(interfaceItem.link.speedMbps) + " Mbps" : "Unknown"],
      ["Streams", String(interfaceItem.streamCount)]
    ]} valueSize={textSizeForCell(cell)} />;
    if (!stream) return <Unavailable />;
    return <SummaryGrid items={[
      ["Total Bitrate", formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)],
      ["Status", stream.active ? "Active" : "Stale"],
      ["Flows", String(selectedFlows.length)],
      ["Roles", selectedFlowKey ? (selectedFlows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")]
    ]} valueSize={textSizeForCell(cell)} />;
  }

  if (cell.type === "stream-bitrate") {
    return stream && !selectedFlowKey ? <MetricChart title="Stream Bitrate" metric={metrics?.streamBitrate} color="var(--chart-rx)" fillHeight yScale={chartYScale} /> : <Unavailable message={selectedFlowKey ? "Available for a stream selection" : undefined} />;
  }

  if (cell.type === "selected-flow-summary") {
    const flow = selectedFlows[0];
    if (!stream || !selectedFlowKey || !flow) return <Unavailable message="Select a flow" />;
    return <SummaryGrid items={[
      ["Role", flow.role],
      ["Source", flow.endpointSrc ?? "-"],
      ["Destination", flow.endpointDst ?? "-"],
      ["Bitrate", formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)]
    ]} valueSize={textSizeForCell(cell)} />;
  }

  if (cell.type === "flows-table") {
    if (!stream) return <Unavailable />;
    return <div className="flow-table inspector-flow-table">{selectedFlows.map((flow) => <div className="flow-row" key={flow.flowKey}><strong>{flow.role}</strong><span>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</span><span>{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span></div>)}</div>;
  }

  if (cell.type === "interface-bandwidth") {
    if (!interfaceItem || stream) return <Unavailable message="Available for an interface selection" />;
    const entries = [
      ["RX usage", formatPercent(interfaceItem.rxRate?.utilization)],
      ["TX usage", formatPercent(interfaceItem.txRate?.utilization)],
      ["RX headroom", formatBitrate(interfaceItem.rxRate?.headroomBps)],
      ["TX headroom", formatBitrate(interfaceItem.txRate?.headroomBps)]
    ] as Array<[string, string]>;
    return <SummaryGrid items={entries} valueSize={textSizeForCell(cell)} />;
  }

  if (cell.type === "metric-chart") {
    const chart = resolveSingleMetric(cell, visibleMetrics, interfaceMetrics, selectedFlowKey);
    if (!chart) return <Unavailable message="Choose a metric" />;
    return <MetricChart title={chart.title} metric={chart.metric} color={chart.color} fillHeight yScale={chartYScale} alertContext={chart.target === "interface" ? interfaceAlertContext : flowAlertContext} />;
  }

  if (cell.type === "metric-group") {
    if (!stream || !visibleMetrics) return <Unavailable />;
    const category = categoryForCell(cell);
    const descriptors = visibleMetrics.descriptors.filter((descriptor) => descriptor.category === category).slice(0, 8);
    return <div className="inspector-metric-group">{descriptors.map((descriptor) => <MetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics} context={flowAlertContext} yScale={chartYScale} />)}</div>;
  }

  if (cell.type === "all-flow-chart-group") {
    if (!stream) return <Unavailable />;
    const descriptors = (visibleMetrics?.descriptors ?? []).filter((descriptor) => descriptor.category !== "stat" && descriptor.key !== "bitrate").sort((a, b) => a.priority - b.priority).slice(0, 5);
    const metricByFlow = new Map((visibleMetrics?.flows ?? []).map((flow) => [flow.flowKey, flow]));
    return <div className="inspector-all-flow-grid">{selectedFlows.map((flow) => <FlowCharts key={flow.flowKey} flow={flow} metrics={metricByFlow.get(flow.flowKey)?.metrics ?? {}} descriptors={descriptors} context={flowAlertContext} yScale={chartYScale} />)}</div>;
  }

  return <Unavailable />;
}

function SummaryGrid({ items, valueSize }: { items: Array<[string, string]>; valueSize: string }) {
  return <div className="graph-summary-band inspector-summary-grid" style={{ "--inspector-value-size": valueSize } as CSSProperties}>{items.map(([label, value]) => <div className="stat-card" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>;
}

function MetricGroup({ descriptor, metrics, context, yScale }: { descriptor: MetricDescriptor; metrics: StreamMetricsResponse; context?: ChartAlertContext; yScale: ChartYScale | undefined }) {
  const entries = metrics.flows.map((flow) => ({ flow, metric: flow.metrics[descriptor.key] })).filter((entry): entry is { flow: StreamMetricsResponse["flows"][number]; metric: TimeSeriesMetric } => Boolean(entry.metric));
  if (entries.length === 0) return null;
  return <section className="metric-group inspector-group"><h3>{descriptor.label}</h3><div className="chart-stack">{entries.map(({ flow, metric }) => <MetricChart key={flow.flowKey} title={flow.label} metric={metric} height={150} color="var(--chart-metric-bitrate)" alertContext={context} yScale={yScale} />)}</div></section>;
}

function FlowCharts({ flow, metrics, descriptors, context, yScale }: { flow: StreamState["flows"][number]; metrics: Record<string, TimeSeriesMetric>; descriptors: MetricDescriptor[]; context?: ChartAlertContext; yScale: ChartYScale | undefined }) {
  const charts = [metrics.bitrate ? { key: "bitrate", label: "Bitrate", metric: metrics.bitrate } : null, ...descriptors.map((descriptor) => metrics[descriptor.key] ? { key: descriptor.key, label: descriptor.label, metric: metrics[descriptor.key] } : null)].filter((entry): entry is { key: string; label: string; metric: TimeSeriesMetric } => Boolean(entry));
  return <section className="graph-flow-card"><div className="graph-flow-card-header"><div><strong>{flow.role}</strong><p>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</p></div><span className="graph-flow-rate">{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span></div><div className="graph-card-grid">{charts.map((chart) => <MetricChart key={chart.key} title={chart.label} metric={chart.metric} compact fillHeight height={64} color="var(--chart-metric-bitrate)" alertContext={context} yScale={yScale} />)}</div></section>;
}

function resolveSingleMetric(cell: InspectorCell, streamMetrics: StreamMetricsResponse | null, interfaceMetrics: InterfaceMetricsResponse | null, selectedFlowKey: string | null) {
  const metricKey = stringParam(cell, "metricKey") || "bitrate";
  if (interfaceMetrics?.metrics[metricKey]) return { title: interfaceMetrics.metrics[metricKey].label, metric: interfaceMetrics.metrics[metricKey], color: "var(--chart-rx)", target: "interface" as const };
  if (metricKey === "stream-bitrate" && streamMetrics?.streamBitrate) return { title: streamMetrics.streamBitrate.label, metric: streamMetrics.streamBitrate, color: "var(--chart-rx)", target: "flow" as const };
  const flow = selectedFlowKey ? streamMetrics?.flows.find((entry) => entry.flowKey === selectedFlowKey) : streamMetrics?.flows[0];
  const metric = flow?.metrics[metricKey];
  return metric ? { title: metric.label, metric, color: "var(--chart-metric-bitrate)", target: "flow" as const } : null;
}

function categoryForCell(cell: InspectorCell): "primary" | "secondary" | "stat" {
  const value = stringParam(cell, "category");
  return value === "secondary" || value === "stat" ? value : "primary";
}

function yScaleForCell(cell: InspectorCell): ChartYScale | undefined {
  const mode = stringParam(cell, "yScale");
  if (mode === "zero") return { mode };
  if (mode === "fixed") {
    const min = numberParam(cell, "yMin");
    const max = numberParam(cell, "yMax");
    return Number.isFinite(min) && Number.isFinite(max) ? { mode, min, max } : { mode: "auto" };
  }
  return undefined;
}

function textSizeForCell(cell: InspectorCell) {
  const value = stringParam(cell, "valueSize");
  return value === "sm" ? "var(--font-size-sm)" : value === "lg" ? "var(--font-size-lg)" : value === "xl" ? "var(--font-size-xl)" : "var(--font-size-md)";
}

function stringParam(cell: InspectorCell, key: string) {
  const value = cell.params?.[key];
  return typeof value === "string" ? value : "";
}

function numberParam(cell: InspectorCell, key: string) {
  const value = Number(cell.params?.[key]);
  return Number.isFinite(value) ? value : Number.NaN;
}

function formatPercent(value: number | undefined) {
  if (value === undefined || !Number.isFinite(value)) return "-";
  return formatMetricValue(value, metricDisplayScale("utilization", "%", [value]));
}

function Unavailable({ message = "Not available for this target" }: { message?: string }) {
  return <div className="inspector-cell-unavailable">{message}</div>;
}
