  if (cell.type === "metric-chart") { const chart = singleMetric(cell, visibleMetrics, interfaceMetrics, selectedFlowKey); return chart ? <MetricChart title={chart.metric.label} metric={chart.metric} color={chart.target === "interface" ? "var(--chart-rx)" : "var(--chart-metric-bitrate)"} fillHeight yScale={yScale} alertContext={chart.target === "interface" ? interfaceContext : flowContext} /> : <Unavailable message="Choose a metric" />; }
