  const thresholds = useMemo(() => thresholdsForMetric(metric, alertContext), [metric, alertContext]);
  const rawValues = useMemo(() => chartValues(metric, thresholds), [metric, thresholds]);
  const displayScale = useMemo(() => metricDisplayScale(metric?.key, metric?.unit, rawValues, scalePreference),  [metric?.key, metric?.unit, rawValues, scalePreference]);
  const yRange = useMemo(() => {
    const values = rawValues.map((value) => value / displayScale.divisor);
    if (yScale?.mode === "fixed" && Number.isFinite(yScale.min) && Number.isFinite(yScale.max) && yScale.min! < yScale.max!) {
      const min = yScale.min! / displayScale.divisor;
      const max = yScale.max! / displayScale.divisor;
      return { min, max, splits: niceLinearRange([min, max], false).splits.filter((value) => value >= min && value <= max) };
    }
    return niceLinearRange(values, yScale?.mode === "zero" || displayScale.includeZero);
  }, [rawValues, displayScale, yScale]);
  const displayThresholds = useMemo(() => thresholds.map((threshold) => ({ ...threshold, value: threshold.value / displayScale.divisor })), [thresholds, displayScale]);
  const thresholdSignature = thresholds.map((threshold) => [threshold.id, threshold.metric, threshold.value, threshold.severity, threshold.recovery, threshold.operator].join(":" )).join("|");
  const scaleSignature = [displayScale.divisor, displayScale.unit, yRange.min, yRange.max, yRange.splits.join(",")].join("|");
  const theme = document.documentElement.dataset.theme ?? "light";

