import { useEffect, useState, type CSSProperties } from "react";
import { getInterfaceMetricsByKey, getStreamMetrics, type MetricsRangeQuery } from "../api/client";
import type { AlertRule, InspectorCell, InterfaceListItem, InterfaceMetricsResponse, MetricDescriptor, StreamMetricsResponse, StreamState, TimeSeriesMetric } from "../types/api";
import { formatBitrate, formatMetricValue, metricDisplayScale, type MetricScalePreference } from "./format";
import { MetricChart, type ChartAlertContext, type ChartYScale } from "./MetricChart";

type Props = { cell: InspectorCell; stream: StreamState | null; metrics: StreamMetricsResponse | null; selectedFlowKey: string | null; interfaceItem: InterfaceListItem | null; interfaceMetrics: InterfaceMetricsResponse | null; alertRules: AlertRule[]; };

export function InspectorCellContent({ cell, stream, metrics, selectedFlowKey, interfaceItem, interfaceMetrics, alertRules }: Props) {
  const ranged = useCellMetrics(cell, stream, interfaceItem, metrics, interfaceMetrics);
  const sourceMetrics = ranged.stream ?? metrics;
  const sourceInterfaceMetrics = ranged.interface ?? interfaceMetrics;
  const flows = stream ? (selectedFlowKey ? stream.flows.filter((flow) => flow.flowKey === selectedFlowKey) : stream.flows) : [];
  const visibleMetrics = sourceMetrics && selectedFlowKey ? { ...sourceMetrics, flows: sourceMetrics.flows.filter((flow) => flow.flowKey === selectedFlowKey) } : sourceMetrics;
  const yScale = yScaleFor(cell);
  const scalePreference = scalePreferenceFor(cell);
  const flowContext: ChartAlertContext | undefined = stream ? { rules: alertRules, target: "flow", proto: stream.proto } : undefined;
  const interfaceContext: ChartAlertContext | undefined = interfaceItem ? { rules: alertRules, target: "interface" } : undefined;
  if (cell.type === "summary") {
    if (interfaceItem && !stream) return <Summary items={[["RX", formatBitrate(interfaceItem.rxBitrate.value ?? interfaceItem.rxBitrate.avg)], ["TX", formatBitrate(interfaceItem.txBitrate.value ?? interfaceItem.txBitrate.avg)], ["Link", interfaceItem.link?.speedMbps ? String(interfaceItem.link.speedMbps) + " Mbps" : "Unknown"], ["Streams", String(interfaceItem.streamCount)]]} size={textSize(cell)} />;
    if (!stream) return <Unavailable />;
    return <Summary items={[["Total Bitrate", formatBitrate(stream.bitrate.value ?? stream.bitrate.avg)], ["Status", stream.active ? "Active" : "Stale"], ["Flows", String(flows.length)], ["Roles", selectedFlowKey ? (flows[0]?.role ?? "flow") : (stream.flowRoles.join(", ") || "default")]]} size={textSize(cell)} />;
  }
  if (cell.type === "stream-bitrate") return stream && !selectedFlowKey ? <MetricChart title="Stream Bitrate" metric={sourceMetrics?.streamBitrate} color="var(--chart-rx)" fillHeight yScale={yScale} scalePreference={scalePreference} /> : <Unavailable message="Available for a stream selection" />;
  if (cell.type === "selected-flow-summary") { const flow = flows[0]; return stream && selectedFlowKey && flow ? <Summary items={[["Role", flow.role], ["Source", flow.endpointSrc ?? "-"], ["Destination", flow.endpointDst ?? "-"], ["Bitrate", formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)]]} size={textSize(cell)} /> : <Unavailable message="Select a flow" />; }
  if (cell.type === "flows-table") return stream ? <div className="flow-table inspector-flow-table">{flows.map((flow) => <div className="flow-row" key={flow.flowKey}><strong>{flow.role}</strong><span>{flow.endpointSrc ?? "-"} <span className="flow-arrow">⟶</span> {flow.endpointDst ?? "-"}</span><span>{formatBitrate(flow.metrics.bitrate?.value ?? flow.metrics.bitrate?.avg)}</span></div>)}</div> : <Unavailable />;
  if (cell.type === "interface-bandwidth") return interfaceItem && !stream ? <Summary items={[["RX usage", percent(interfaceItem.rxRate?.utilization)], ["TX usage", percent(interfaceItem.txRate?.utilization)], ["RX headroom", formatBitrate(interfaceItem.rxRate?.headroomBps)], ["TX headroom", formatBitrate(interfaceItem.txRate?.headroomBps)]]} size={textSize(cell)} /> : <Unavailable message="Available for an interface selection" />;
  if (cell.type === "metric-chart") { const chart = singleMetric(cell, visibleMetrics, sourceInterfaceMetrics, selectedFlowKey); return chart ? <MetricChart title={chart.metric.label} metric={chart.metric} color={chart.target === "interface" ? "var(--chart-rx)" : "var(--chart-metric-bitrate)"} fillHeight yScale={yScale} scalePreference={scalePreference} alertContext={chart.target === "interface" ? interfaceContext : flowContext} /> : <Unavailable message="Choose a metric" />; }
  if (cell.type === "metric-group") { const category = categoryFor(cell); const descriptors = visibleMetrics?.descriptors.filter((descriptor) => descriptor.category === category).slice(0, 8) ?? []; return descriptors.length ? <div className="inspector-metric-group">{descriptors.map((descriptor) => <MetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics!} context={flowContext} yScale={yScale} scalePreference={scalePreference} />)}</div> : <Unavailable />; }
  if (cell.type === "all-flow-chart-group") { const descriptors = (visibleMetrics?.descriptors ?? []).filter((descriptor) => descriptor.category !== "stat" && descriptor.key !== "bitrate").sort((a, b) => a.priority - b.priority).slice(0, 5); const byFlow = new Map((visibleMetrics?.flows ?? []).map((flow) => [flow.flowKey, flow.metrics])); return stream ? <div className="inspector-all-flow-grid">{flows.map((flow) => <FlowCharts key={flow.flowKey} flow={flow} metrics={byFlow.get(flow.flowKey) ?? {}} descriptors={descriptors} context={flowContext} yScale={yScale} scalePreference={scalePreference} />)}</div> : <Unavailable />; }
  return <Unavailable />;
}

