    timeline,
    timelineEvents,
    timelineGaps,
    timelineWindow,
    timelineAvailable,
    timelineSource,
    timelineLoading,
    timelineLoadState,
    historyStreamsLoading,
    eventsLoading,
    summary,
    liveSummary,
    liveUpdateReceivedAt,
    selectedListItem,
    selectedStream,
    selectedMetrics,
    selectedMetricsLoadState,
