      {cell.type === "metric-group" && <select value={inspectorCellTextParam(cell, "category") || "primary"} onChange={(event) => updateInspectorCellParams(cell.id, { category: event.target.value })} aria-label="Metric category"><option value="primary">Primary</option><option value="secondary">Secondary</option><option value="stat">Stats</option></select>}
      {(cell.type === "metric-chart" || cell.type === "stream-bitrate" || cell.type === "metric-group" || cell.type === "all-flow-chart-group") && <><select value={inspectorCellTextParam(cell, "scalePreference") || "auto"} onChange={(event) => updateInspectorCellParams(cell.id, { scalePreference: event.target.value })} aria-label="Unit scale"><option value="auto">Unit: Auto</option><option value="base">Unit: Base</option><option value="K">Unit: K</option><option value="M">Unit: M</option><option value="G">Unit: G</option><option value="T">Unit: T</option></select><select value={inspectorCellTextParam(cell, "xRange") || "inherit"} onChange={(event) => updateInspectorCellParams(cell.id, { xRange: event.target.value })} aria-label="X range"><option value="inherit">X: Inspector</option><option value="1m">X: 1m</option><option value="5m">X: 5m</option><option value="10m">X: 10m</option><option value="30m">X: 30m</option><option value="1h">X: 1h</option><option value="3h">X: 3h</option><option value="6h">X: 6h</option><option value="12h">X: 12h</option><option value="24h">X: 24h</option></select><select value={yScale} onChange={(event) => updateInspectorCellParams(cell.id, { yScale: event.target.value })} aria-label="Y axis"><option value="auto">Y: Auto</option><option value="zero">Y: Zero</option><option value="fixed">Y: Fixed</option></select></>}
      {yScale === "fixed" && <><input type="number" value={inspectorCellTextParam(cell, "yMin")} onChange={(event) => updateInspectorCellParams(cell.id, { yMin: event.target.value })} aria-label="Y minimum" placeholder="Y min" /><input type="number" value={inspectorCellTextParam(cell, "yMax")} onChange={(event) => updateInspectorCellParams(cell.id, { yMax: event.target.value })} aria-label="Y maximum" placeholder="Y max" /></>}
      {(cell.type === "summary" || cell.type === "selected-flow-summary" || cell.type === "interface-bandwidth") && <select value={inspectorCellTextParam(cell, "valueSize") || "md"} onChange={(event) => updateInspectorCellParams(cell.id, { valueSize: event.target.value })} aria-label="Value size"><option value="sm">Text: Small</option><option value="md">Text: Medium</option><option value="lg">Text: Large</option><option value="xl">Text: Extra large</option></select>}
    </>;
  };

  const renderInspectorView = () => <section className="inspector-layout-view">
