      <label className="detail-range-select"><span>{t("dashboard.layout")}</span><select value={inspectorLayout.id} onChange={(event) => setInspectorLayoutId(event.target.value)}>{inspectorLayouts.map((layout) => <option key={layout.id} value={layout.id}>{layout.name}</option>)}</select></label>
      <button type="button" className={"dashboard-action-button button-with-icon " + (inspectorEditing ? "primary" : "")} onClick={() => setInspectorEditing((editing) => !editing)}><Icon name={inspectorEditing ? "done" : "edit"} size={15} />{inspectorEditing ? t("dashboard.done") : t("dashboard.editLayout")}</button>
      {inspectorEditing && <><button type="button" className="dashboard-action-button button-with-icon" onClick={addInspectorCell}><Icon name="add" size={15} />{t("dashboard.addCell")}</button><button type="button" className="dashboard-action-button button-with-icon" onClick={resetInspectorLayout}><Icon name="reset" size={15} />{t("dashboard.reset")}</button><button type="button" className="dashboard-action-button button-with-icon primary" onClick={() => void saveInspectorLayout()} disabled={inspectorSaveState === "saving"}><Icon name={inspectorSaveState === "saved" ? "done" : "save"} size={15} />{inspectorSaveState === "saving" ? "Saving" : inspectorSaveState === "saved" ? "Saved" : inspectorSaveState === "error" ? "Retry save" : "Save"}</button></>}
    </div>} />
    <div className="inspector-layout-body"><InspectorGrid layout={inspectorLayout} editing={inspectorEditing} editMode={appConfig.dashboardLayoutEditMode} renderCell={(cell) => <InspectorCellContent cell={cell} stream={detailStream} metrics={selectedMetrics} selectedFlowKey={selectedFlowKey} interfaceItem={selectedInterfaceKey && !selectedStreamKey ? selectedInterface : null} interfaceMetrics={selectedInterfaceKey && !selectedStreamKey ? selectedInterfaceMetrics : null} alertRules={alertRules} />} renderCellActions={renderInspectorCellActions} onLayoutsChange={updateInspectorLayouts} onUpdateCell={updateInspectorCell} onRemoveCell={removeInspectorCell} /></div>
  </section>;

  const renderDashboardView = () => (
    <section className="main-tab-view dashboard-view">
      <PaneHeader
        className="dashboard-toolbar"
        icon="dashboard"
        title={t("nav.dashboard")}
        meta={dashboardContextLabel + " · " + dashboardLayout.cells.length + " cells / " + dashboardLayout.columns + " columns"}
        actions={<div className="dashboard-actions">
          <label className="detail-range-select dashboard-time-range">
            <span>{t("common.range")}</span>
            <select value={dashboardRange} onChange={(event) => setDashboardRange(event.target.value)}>
              {RANGE_OPTIONS.map((range) => <option key={range} value={range}>{range}</option>)}
                selectedStreamKey={selectedStreamKey}
                selectedFlowKey={selectedFlowKey}
                selectedInterfaceId={selectedInterface?.interfaceId ?? null}
                selectedTimeSec={tabContextTimeSec}
                onSelectTime={selectGlobalTime}
                selectedEvent={selectedEvent}
                onSelectEvent={setSelectedEvent}
                initialQuery={query}
            />
          </section>
        )}
        {standaloneView === "detail" && (
          <section className="standalone-view standalone-detail">
            {renderStatusHeader(t("nav.inspector"), "detail")}
            {selectedInterface && !selectedStreamKey ? (
              <InterfaceDetailPane
                item={selectedInterface}
                metrics={selectedInterfaceMetrics}
                mode={detailMode}
                onChangeMode={setDetailMode}
                onMinimizeWidth={() => undefined}
                onRestoreWidth={() => undefined}
                onMaximizeWidth={() => undefined}
                isWidthMinimized={false}
                isWidthRestored
