            <div className="standalone-inspector-cell-body"><InspectorCellContent cell={linkedCell} stream={detailStreamForStandalone} metrics={selectedMetrics} selectedFlowKey={selectedFlowKey} interfaceItem={selectedInterfaceKey && !selectedStreamKey ? selectedInterface : null} interfaceMetrics={selectedInterfaceKey && !selectedStreamKey ? selectedInterfaceMetrics : null} alertRules={alertRules} /></div>
          </> : <div className="empty-chart">Inspector cell is no longer available.</div>}
        </section>}
      <InspectorTargetDrawer
