import { useCallback, useMemo, useRef, useState } from "react";

export type ResourceLoadState =
  | { phase: "idle" | "ready"; requestId: number }
  | { phase: "loading" | "refreshing"; requestId: number }
  | { phase: "error"; requestId: number; message: string };

export function useResourceLoadState(initialPhase: "idle" | "ready" = "idle") {
  const requestIdRef = useRef(0);
  const [state, setState] = useState<ResourceLoadState>({ phase: initialPhase, requestId: 0 });

  const begin = useCallback((phase: "loading" | "refreshing") => {
    const requestId = requestIdRef.current + 1;
    requestIdRef.current = requestId;
    setState({ phase, requestId });
    return requestId;
  }, []);
  const succeed = useCallback((requestId: number) => {
    if (requestId === requestIdRef.current) setState({ phase: "ready", requestId });
  }, []);
  const succeedAfterPaint = useCallback((requestId: number) => {
    requestAnimationFrame(() => { if (requestId === requestIdRef.current) setState({ phase: "ready", requestId }); });
  }, []);
  const fail = useCallback((requestId: number, error: unknown) => {
    if (requestId !== requestIdRef.current) return;
    setState({ phase: "error", requestId, message: error instanceof Error ? error.message : "failed to load data" });
  }, []);
  const reset = useCallback(() => {
    const requestId = requestIdRef.current + 1;
    requestIdRef.current = requestId;
    setState({ phase: "idle", requestId });
  }, []);

  return useMemo(() => ({ state, begin, succeed, succeedAfterPaint, fail, reset }), [state, begin, succeed, succeedAfterPaint, fail, reset]);
}
