  }, []);
  const reset = useCallback(() => {
    const requestId = requestIdRef.current + 1;
    requestIdRef.current = requestId;
    setState({ phase: "idle", requestId });
  }, []);

  return useMemo(() => ({ state, begin, succeed, succeedAfterPaint, fail, reset }), [state, begin, succeed, succeedAfterPaint, fail, reset]);
}
