      const rawCells = input.layouts[breakpoint];
      if (!Array.isArray(rawCells)) continue;
      const normalized = rawCells.map((cell: any, index: number) => normalizeInspectorCell(cell, index, responsiveColumns[breakpoint])).filter(Boolean);
