perl -0pi -e 's@  const addInspectorCell = \(\) => \{
    const id = "inspector-" \+ Date\.now\(\)\.toString\(36\);
    const cell: InspectorCell = \{ id, title: "Metric", type: "metric-chart", grid: \{ x: 0, y: nextInspectorY\(inspectorLayout\.cells\), w: 12, h: 8 \}, params: \{ metricKey: "bitrate" \} \};@  const addInspectorCell = () => {
    const id = "inspector-" + Date.now().toString(36);
    const metricKey = inspectorTargetKind === "interface" ? "rx.bitrate" : inspectorTargetKind === "stream" ? "stream-bitrate" : "bitrate";
    const cell: InspectorCell = { id, title: "Metric", type: "metric-chart", grid: { x: 0, y: nextInspectorY(inspectorLayout.cells), w: 12, h: 8 }, params: { metricKey } };@; s@  const resetInspectorLayout = \(\) => \{
    setInspectorSaveState\("idle"\);
    setInspectorLayouts\(\(layouts\) => \[DEFAULT_INSPECTOR_LAYOUT, \.\.\.layouts\.filter\(\(layout\) => layout\.id !== DEFAULT_INSPECTOR_LAYOUT\.id\)\]\);
    setInspectorLayoutId\(DEFAULT_INSPECTOR_LAYOUT\.id\);
  \};@  const resetInspectorLayout = () => {
    const defaultLayout = DEFAULT_INSPECTOR_LAYOUTS.find((layout) => layout.targetKind === inspectorTargetKind) ?? DEFAULT_INSPECTOR_LAYOUT;
    setInspectorSaveState("idle");
    setInspectorLayouts((layouts) => [defaultLayout, ...layouts.filter((layout) => layout.targetKind !== inspectorTargetKind || layout.id !== defaultLayout.id)]);
    setInspectorLayoutId(defaultLayout.id);
  };@; s@inspectorLayouts\.map\(\(layout\) => <option key=\{layout\.id\} value=\{layout\.id\}>\{layout\.name\}</option>\)@inspectorLayoutsForTarget.map((layout) => <option key={layout.id} value={layout.id}>{layout.name}</option>)@; s@onChange=\{\(event\) => setInspectorLayoutId\(event\.target\.value\)\}@onChange={(event) => setInspectorLayoutId(event.target.value)}@; s@<InspectorGrid layout=\{inspectorLayout\}@<InspectorGrid targetKind={inspectorTargetKind} layout={inspectorLayout}@g; s@selectedFlowKey=\{selectedFlowKey\}
        onClose@selectedFlowKey={selectedFlowKey}
        selectedInterfaceKey={selectedInterfaceKey}
        onClose@g; s@onSelectInterface=\{\(\) => undefined\}@onSelectInterface={selectInspectorInterface}@g' fe/client/src/App.tsx
rg -n -C 2 'resetInspectorLayout|targetKind=|selectedInterfaceKey=\{selectedInterfaceKey\}|onSelectInterface=\{selectInspectorInterface\}|inspectorLayoutsForTarget\.map' fe/client/src/App.tsx

