import { Responsive, horizontalCompactor, noCompactor, useContainerWidth, verticalCompactor, type Compactor, type Layout, type LayoutItem } from "react-grid-layout";
import { useCallback, useMemo, useState, type ReactNode, type Ref } from "react";
import type { InspectorCell, InspectorCellType, InspectorLayout, InspectorResponsiveLayouts, InspectorTargetKind } from "../types/api";
import { Icon } from "./ui/Icon";

const BREAKPOINTS = { desktop: 1200, tablet: 700, mobile: 0 } as const;
const COLUMNS = { desktop: 24, tablet: 12, mobile: 4 } as const;
type Breakpoint = keyof typeof COLUMNS;
const fixedCompactor: Compactor = { ...noCompactor, preventCollision: true };
const pushCompactor: Compactor = { ...noCompactor, preventCollision: false };
const CELL_TYPES: InspectorCellType[] = ["summary", "stream-bitrate", "selected-flow-summary", "flows-table", "metric-chart", "metric-group", "all-flow-chart-group", "interface-bandwidth"];
const CELL_TITLES: Record<InspectorCellType, string> = { summary: "Summary", "stream-bitrate": "Stream Bitrate", "selected-flow-summary": "Selected Flow", "flows-table": "Flows", "metric-chart": "Metric", "metric-group": "Metric Group", "all-flow-chart-group": "Flow Metrics", "interface-bandwidth": "Link Capacity" };
const CELL_TYPES_BY_TARGET: Record<InspectorTargetKind, InspectorCellType[]> = { interface: ["summary", "interface-bandwidth", "metric-chart"], stream: ["summary", "stream-bitrate", "flows-table", "metric-chart", "metric-group", "all-flow-chart-group"], flow: ["summary", "selected-flow-summary", "metric-chart", "metric-group"] };

type Props = {
  targetKind: InspectorTargetKind;
  layout: InspectorLayout;
  editing: boolean;
  editMode: number;
  renderCell: (cell: InspectorCell) => ReactNode;
  renderCellActions?: (cell: InspectorCell, editing: boolean) => ReactNode;
  onLayoutsChange: (layouts: InspectorResponsiveLayouts) => void;
  onUpdateCell: (cellId: string, updater: (cell: InspectorCell) => InspectorCell) => void;
  onRemoveCell: (cellId: string) => void;
};

export function InspectorGrid({ targetKind, layout, editing, editMode, renderCell, renderCellActions, onLayoutsChange, onUpdateCell, onRemoveCell }: Props) {
  const { width, containerRef, mounted } = useContainerWidth({ initialWidth: 1280 });
  const [activeBreakpoint, setActiveBreakpoint] = useState<Breakpoint>(breakpointForWidth(width));
  const cellsByBreakpoint = useMemo(() => responsiveCells(layout.cells, layout.layouts), [layout.cells, layout.layouts]);
  const activeCells = cellsByBreakpoint[activeBreakpoint] ?? layout.cells;
  const layouts = useMemo(() => Object.fromEntries((Object.keys(COLUMNS) as Breakpoint[]).map((breakpoint) => [breakpoint, cellsByBreakpoint[breakpoint].map(toLayoutItem)])) as unknown as Record<Breakpoint, Layout>, [cellsByBreakpoint]);
  const onLayoutChange = useCallback((_layout: Layout, nextLayouts: Partial<Record<string, Layout>>) => {
    if (!editing) return;
    const next = {} as InspectorResponsiveLayouts;
    for (const breakpoint of Object.keys(COLUMNS) as Breakpoint[]) {
      if (nextLayouts[breakpoint]) next[breakpoint] = merge(cellsByBreakpoint[breakpoint], nextLayouts[breakpoint]!);
    }
    onLayoutsChange(next);
  }, [cellsByBreakpoint, editing, onLayoutsChange]);
  return { mode: "pinned", streamKey, flowKey: flowKey || null };
}

function dashboardTargetLabel(target: { streamKey: string; flowKey: string | null }, streams: StreamListItem[]) {
  const stream = streams.find((item) => item.streamKey === target.streamKey);
  const flow = target.flowKey ? stream?.flows.find((item) => item.flowKey === target.flowKey) : undefined;
  if (flow) return `${flow.endpointSrc ?? "Unknown endpoint"} ⟶ ${flow.endpointDst ?? "Unknown endpoint"}`;
  return stream ? streamEndpointLabel(stream) : target.streamKey;
}

function InspectorTargetDrawer({
  open,
  modal = true,
  streams,
  interfaces,
  selectedStreamKey,
  selectedFlowKey,
  selectedInterfaceKey,
  onClose,
  onSelectStream,
  onSelectFlow
}: {
  open: boolean;
  modal?: boolean;
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceKey: string | null;
  onClose: () => void;
  onSelectStream: (streamKey: string) => void;
  onSelectFlow: (streamKey: string, flowKey: string) => void;
}) {
  const { t } = useI18n();
    >
      <header className="inspector-target-drawer-header">
        <div><strong>{t("dashboard.selectInspectorTarget")}</strong><small>{t("dashboard.selectStreamOrFlow")}</small></div>
        <button type="button" className="icon-button" onClick={onClose} aria-label={t("dashboard.closeTargetSelector")} title={t("common.close")}><Icon name="close" size={17} /></button>
      </header>
      <div className="inspector-target-drawer-search"><SearchInput value={query} onChange={setQuery} placeholder={t("dashboard.searchStreamsOrFlows")} label={t("dashboard.searchStreamsOrFlows")} /></div>
      <div className="inspector-target-drawer-list">
        {visibleStreams.length === 0 ? <div className="inspector-target-drawer-empty">{t("dashboard.noMatchingTargets")}</div> : <StreamTable
          streams={visibleStreams}
          interfaces={visibleInterfaces}
          selectedStreamKey={selectedStreamKey}
          selectedFlowKey={selectedFlowKey}
          selectedInterfaceKey={null}
          overviewMode={false}
          expandLevel="flow"
          pickerMode
          onSelectInterface={selectInspectorInterface}
          onSelectStream={onSelectStream}
          onSelectFlow={onSelectFlow}
        />}
      </div>

