export function descriptorForMetric(key: string): MetricDescriptor {
  const rules: Array<Partial<MetricDescriptor> & { pattern: RegExp }> = [
    { pattern: /^bitrate$/, category: "primary", display: "range-line", priority: 10, unit: "bps" },
    { pattern: /^packet_rate$/, category: "primary", display: "range-line", priority: 20, unit: "pps" },
    { pattern: /^jitter$/, category: "primary", display: "range-line", priority: 30, unit: "s" },
    { pattern: /^rtt$/, category: "primary", display: "range-line", priority: 40, unit: "ms" },
    { pattern: /^bandwidth$/, category: "primary", display: "range-line", priority: 50, unit: "bps" },
    { pattern: /^(rx|tx)\.utilization$/, category: "primary", display: "range-line", priority: 60 },
    { pattern: /^(rx|tx)\.headroom$/, category: "primary", display: "range-line", priority: 70, unit: "bps" },
    { pattern: /^seq_stats\.(dup|gap|reorder)$/, category: "stat", display: "stat", priority: 100 }
  ];

  const match = rules.find((rule) => rule.pattern.test(key));
  return {
    key,
    label: labelForMetric(key),
    unit: match?.unit,
    category: match?.category ?? "secondary",
    display: match?.display ?? "range-line",
    priority: match?.priority ?? 1000
  };
}

function labelForMetric(key: string) {
  return key
    .split(".")
    .map((part) => part.replace(/_/g, " "))
    .join(" / ")
    .replace(/\b\w/g, (char) => char.toUpperCase());
}
import { Responsive, horizontalCompactor, noCompactor, useContainerWidth, verticalCompactor, type Compactor, type Layout, type LayoutItem } from "react-grid-layout";
import { useCallback, useMemo, useState, type ReactNode, type Ref } from "react";
import type { InspectorCell, InspectorCellType, InspectorLayout, InspectorResponsiveLayouts, InspectorTargetKind } from "../types/api";
import { Icon } from "./ui/Icon";

const BREAKPOINTS = { desktop: 1200, tablet: 700, mobile: 0 } as const;
const COLUMNS = { desktop: 24, tablet: 12, mobile: 4 } as const;
type Breakpoint = keyof typeof COLUMNS;
const fixedCompactor: Compactor = { ...noCompactor, preventCollision: true };
const pushCompactor: Compactor = { ...noCompactor, preventCollision: false };
const CELL_TITLES: Record<InspectorCellType, string> = { summary: "Summary", "stream-bitrate": "Stream Bitrate", "selected-flow-summary": "Selected Flow", "flows-table": "Flows", "metric-chart": "Metric", "metric-group": "Metric Group", "all-flow-chart-group": "Flow Metrics", "interface-bandwidth": "Link Capacity" };
const CELL_TYPES_BY_TARGET: Record<InspectorTargetKind, InspectorCellType[]> = { interface: ["summary", "interface-bandwidth", "metric-chart"], stream: ["summary", "stream-bitrate", "flows-table", "metric-chart", "metric-group", "all-flow-chart-group"], flow: ["summary", "selected-flow-summary", "metric-chart", "metric-group"] };

type Props = {
  targetKind: InspectorTargetKind;
  layout: InspectorLayout;
  editing: boolean;
  editMode: number;
  renderCell: (cell: InspectorCell) => ReactNode;
  renderCellActions?: (cell: InspectorCell, editing: boolean) => ReactNode;
  onLayoutsChange: (layouts: InspectorResponsiveLayouts) => void;
  onUpdateCell: (cellId: string, updater: (cell: InspectorCell) => InspectorCell) => void;
  onRemoveCell: (cellId: string) => void;
};

export function InspectorGrid({ targetKind, layout, editing, editMode, renderCell, renderCellActions, onLayoutsChange, onUpdateCell, onRemoveCell }: Props) {
  const { width, containerRef, mounted } = useContainerWidth({ initialWidth: 1280 });
  const [activeBreakpoint, setActiveBreakpoint] = useState<Breakpoint>(breakpointForWidth(width));
  const cellsByBreakpoint = useMemo(() => responsiveCells(layout.cells, layout.layouts), [layout.cells, layout.layouts]);
  const activeCells = cellsByBreakpoint[activeBreakpoint] ?? layout.cells;
  const layouts = useMemo(() => Object.fromEntries((Object.keys(COLUMNS) as Breakpoint[]).map((breakpoint) => [breakpoint, cellsByBreakpoint[breakpoint].map(toLayoutItem)])) as unknown as Record<Breakpoint, Layout>, [cellsByBreakpoint]);
  const onLayoutChange = useCallback((_layout: Layout, nextLayouts: Partial<Record<string, Layout>>) => {
    if (!editing) return;
    const next = {} as InspectorResponsiveLayouts;
    for (const breakpoint of Object.keys(COLUMNS) as Breakpoint[]) {
      if (nextLayouts[breakpoint]) next[breakpoint] = merge(cellsByBreakpoint[breakpoint], nextLayouts[breakpoint]!);
    }
    onLayoutsChange(next);
  }, [cellsByBreakpoint, editing, onLayoutsChange]);
  return <div ref={containerRef as unknown as Ref<HTMLDivElement>} className={"dashboard-rgl-shell inspector-rgl-shell " + (editing ? "is-editing" : "is-viewing")}>
    {mounted && <Responsive className="inspector-rgl" width={width} layouts={layouts} breakpoints={BREAKPOINTS} cols={COLUMNS} rowHeight={layout.rowHeight} margin={[10, 10]} containerPadding={[0, 0]}
      dragConfig={{ enabled: editing, handle: ".inspector-drag-handle", cancel: ".inspector-cell-body, .inspector-cell-actions, input, select, .inspector-cell-remove, a, button" }}
      resizeConfig={{ enabled: editing, handles: ["se"] }} compactor={compactor(editMode)} autoSize onBreakpointChange={(value) => setActiveBreakpoint(toBreakpoint(value))} onLayoutChange={onLayoutChange}>
      {activeCells.map((cell) => <section key={cell.id} className={"dashboard-cell inspector-cell inspector-cell-" + cell.type}>
        <header className="pane-header pane-header-compact dashboard-cell-header inspector-cell-header">{editing ? <>
          <button type="button" className="dashboard-drag-handle inspector-drag-handle" aria-label="Move cell" title="Drag to move"><Icon name="drag" size={16} /></button>
          <input value={cell.title} onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, title: event.target.value }))} aria-label="Cell title" />
          <select value={cell.type} onChange={(event) => { const type = event.target.value as InspectorCellType; onUpdateCell(cell.id, (current) => ({ ...current, type, title: CELL_TITLES[type] })); }} aria-label="Cell type">{CELL_TYPES_BY_TARGET[targetKind].map((type) => <option key={type} value={type}>{CELL_TITLES[type]}</option>)}</select>
          {renderCellActions && <div className="dashboard-cell-actions inspector-cell-actions">{renderCellActions(cell, true)}</div>}
          <button type="button" className="dashboard-cell-remove inspector-cell-remove" onClick={() => onRemoveCell(cell.id)} disabled={activeCells.length <= 1} aria-label="Remove cell" title="Remove cell"><Icon name="delete" size={15} /></button>
        </> : <><strong className="pane-header-title">{cell.title}</strong>{renderCellActions && <div className="dashboard-cell-actions inspector-cell-actions">{renderCellActions(cell, false)}</div>}</>}</header>
        <div className="dashboard-cell-body inspector-cell-body">{renderCell(cell)}</div>
      </section>)}
    </Responsive>}
  </div>;
}

function compactor(editMode: number): Compactor { if (editMode === 1) return verticalCompactor; if (editMode === 2) return horizontalCompactor; return editMode === 3 ? pushCompactor : fixedCompactor; }
function breakpointForWidth(width: number): Breakpoint { return width >= BREAKPOINTS.desktop ? "desktop" : width >= BREAKPOINTS.tablet ? "tablet" : "mobile"; }
function toBreakpoint(value: string): Breakpoint { return value === "mobile" || value === "tablet" || value === "desktop" ? value : "desktop"; }
function toLayoutItem(cell: InspectorCell): LayoutItem { const minimum = cell.type === "metric-chart" || cell.type === "stream-bitrate" ? { minW: 4, minH: 5 } : cell.type === "all-flow-chart-group" ? { minW: 6, minH: 6 } : { minW: 2, minH: 3 }; return { i: cell.id, x: cell.grid.x, y: cell.grid.y, w: cell.grid.w, h: cell.grid.h, ...minimum, maxW: 48, maxH: 40, isBounded: true }; }
function responsiveCells(cells: InspectorCell[], saved: InspectorResponsiveLayouts | undefined): Record<Breakpoint, InspectorCell[]> { return { desktop: saved?.desktop ?? cells, tablet: saved?.tablet ?? fallback(cells, 12, 2), mobile: saved?.mobile ?? fallback(cells, 4, 1) }; }
function fallback(cells: InspectorCell[], columns: number, count: number) { const width = Math.floor(columns / count); const result: InspectorCell[] = []; let y = 0; for (let index = 0; index < cells.length; index += count) { const row = cells.slice(index, index + count); const height = Math.max(...row.map((cell) => cell.grid.h), 3); row.forEach((cell, column) => result.push({ ...cell, grid: { x: column * width, y, w: width, h: cell.grid.h } })); y += height; } return result; }
function merge(cells: InspectorCell[], layout: Layout) { const positions = new Map(layout.map((item) => [item.i, item])); return cells.map((cell) => { const item = positions.get(cell.id); return item ? { ...cell, grid: { x: item.x, y: item.y, w: item.w, h: item.h } } : cell; }); }
  border: 1px solid var(--line);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  background: var(--bg-subtle);
}

.inspector-rgl-shell { height: 100%; overflow: auto; background: var(--bg-subtle); }
.inspector-rgl { min-height: 100%; }
.inspector-cell { border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); overflow: hidden; }
.inspector-cell-header { min-height: 32px; padding: var(--space-1) 6px; border-bottom: 1px solid var(--line); background: var(--surface-muted); }
.inspector-cell-header input, .inspector-cell-header select { min-width: 0; min-height: 24px; padding: 0 6px; border-radius: var(--radius-sm); font-size: var(--font-size-xs); }
.inspector-cell-header input { flex: 1 1 90px; }
.inspector-cell-actions { display: flex; min-width: 0; align-items: center; gap: var(--space-1); margin-left: auto; }
.inspector-drag-handle, .inspector-cell-remove { min-height: 24px; padding: 0 5px; border-radius: var(--radius-sm); }
.inspector-cell-body { min-height: 0; height: calc(100% - 32px); overflow: auto; padding: var(--space-2); background: var(--surface); }
.inspector-rgl-shell.is-editing .inspector-cell { border-color: var(--accent-border); }
.inspector-rgl-shell.is-editing .react-grid-item.react-draggable-dragging .inspector-cell { box-shadow: var(--shadow-md); }
.inspector-rgl-shell.is-editing .react-resizable-handle::after { border-color: var(--accent); }
.inspector-summary-grid { height: 100%; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); }
.inspector-summary-grid .stat-card strong { font-size: var(--inspector-value-size); }
.inspector-cell-unavailable { display: grid; place-items: center; min-height: 100%; color: var(--muted); font-size: var(--font-size-sm); }
.inspector-all-flow-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: var(--space-2); }
.inspector-metric-group > .metric-group { margin-bottom: var(--space-2); }
.inspector-flow-table { min-height: 100%; }

@media (max-width: 720px) {
  .inspector-layout-view { padding: var(--space-2); }

