          <button type="button" className="dashboard-drag-handle inspector-drag-handle" aria-label="Move cell" title="Drag to move"><Icon name="drag" size={16} /></button>
          <input value={cell.title} onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, title: event.target.value }))} aria-label="Cell title" />
          <select value={cell.type} onChange={(event) => { const type = event.target.value as InspectorCellType; onUpdateCell(cell.id, (current) => ({ ...current, type, title: CELL_TITLES[type] })); }} aria-label="Cell type">{CELL_TYPES_BY_TARGET[targetKind].map((type) => <option key={type} value={type}>{CELL_TITLES[type]}</option>)}</select>
          {renderCellActions && <div className="dashboard-cell-actions inspector-cell-actions">{renderCellActions(cell, true)}</div>}
          <button type="button" className="dashboard-cell-remove inspector-cell-remove" onClick={() => onRemoveCell(cell.id)} disabled={activeCells.length <= 1} aria-label="Remove cell" title="Remove cell"><Icon name="delete" size={15} /></button>
        </> : <><strong className="pane-header-title">{cell.title}</strong>{renderCellActions && <div className="dashboard-cell-actions inspector-cell-actions">{renderCellActions(cell, false)}</div>}</>}</header>
        <div className="dashboard-cell-body inspector-cell-body">{renderCell(cell)}</div>
      </section>)}
    </Responsive>}
  </div>;
