output.text:
.main-tab-detail .detail-header {
  min-height: var(--pane-header-height);
  margin: 0;
  padding: 0 var(--space-2);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: var(--surface);
}

.main-tab-detail .detail-header h2 {
  font-size: var(--font-size-sm);
}

.main-tab-detail .detail-body {
  min-height: 0;
  padding: var(--space-2);
  background: var(--surface);
}

.pane-width-controls .size-button {
  display: inline-grid;
  place-items: center;
}


/* Inspector-specific responsive layout cells. */
.inspector-layout-view {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  padding: var(--space-3);
}

.inspector-layout-toolbar {
  min-height: var(--pane-header-height);
  padding: 0 var(--space-2);
  border-bottom: 0;
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}

.inspector-layout-body {
  min-height: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 0 0 var(--radius-md) var(--radius-md);
  background: var(--bg-subtle);
}

.inspector-rgl-shell { height: 100%; overflow: auto; background: var(--bg-subtle); }
.inspector-rgl { min-height: 100%; }
.inspector-cell { border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); overflow: hidden; }
.inspector-cell-header { min-height: 32px; padding: var(--space-1) 6px; border-bottom: 1px solid var(--line); background: var(--surface-muted); }
.inspector-cell-header input, .inspector-cell-header select { min-width: 0; min-height: 24px; padding: 0 6px; border-radius: var(--radius-sm); font-size: var(--font-size-xs); }
.inspector-cell-header input { flex: 1 1 90px; }
.inspector-cell-actions { display: flex; min-width: 0; align-items: center; gap: var(--space-1); margin-left: auto; }
.inspector-drag-handle, .inspector-cell-remove { min-height: 24px; padding: 0 5px; border-radius: var(--radius-sm); }
.inspector-cell-body { min-height: 0; height: calc(100% - 32px); overflow: auto; padding: var(--space-2); background: var(--surface); }
.inspector-rgl-shell.is-editing .inspector-cell { border-color: var(--accent-border); }
.inspector-rgl-shell.is-editing .react-grid-item.react-draggable-dragging .inspector-cell { box-shadow: var(--shadow-md); }
.inspector-rgl-shell.is-editing .react-resizable-handle::after { border-color: var(--accent); }
.inspector-summary-grid { height: 100%; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); }
.inspector-summary-grid .stat-card strong { font-size: var(--inspector-value-size); }
.inspector-cell-unavailable { display: grid; place-items: center; min-height: 100%; color: var(--muted); font-size: var(--font-size-sm); }
.inspector-all-flow-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: var(--space-2); }
.pane-header {
  min-height: var(--pane-header-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  padding: 0 var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.pane-header-copy,
.pane-header-actions {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.pane-header-icon {
  flex: 0 0 auto;
  color: var(--muted);
}

.pane-header-title-with-icon {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}

.pane-header-title {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  white-space: nowrap;
}

.pane-header-meta {
  overflow: hidden;
  color: var(--muted);
  font-size: var(--font-size-xs);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.search-input {
  position: relative;
  display: block;
  min-width: 0;
}

.search-input > svg {
  position: absolute;
  top: 50%;
  left: 9px;
  color: var(--muted);
  font-size: var(--font-size-md);
  line-height: 1;
  pointer-events: none;
  transform: translateY(-50%);
}

.search-input input {
  width: 100%;
  min-height: var(--control-height);
  padding: 0 30px 0 28px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface-muted);
  color: var(--text-strong);
}

.search-input .search-clear {
  right: 5px;
  width: 20px;
  height: 20px;
  min-height: 20px;
  font-size: var(--font-size-md);
}

.list-toolbar,
.timeline-header,
.events-header,
.detail-header,
.topology-header,
.dashboard-toolbar {
  min-height: var(--pane-header-height);
}

.list-toolbar h2,
.timeline-header h3,
.events-header h3,
.topology-header h2,
.dashboard-toolbar h2 {
  margin: 0;
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-compact);
}

.list-toolbar p,
.timeline-header p,
.topology-header p,
.dashboard-toolbar p {
  margin: 0;
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.dashboard-toolbar {
  margin: 0;
}

/* A tab and a dashboard cell share the same flat header/body boundary. */
.main-tab-view {
  min-height: 0;
  height: 100%;
  padding: var(--space-3);
  overflow: hidden;
}

.main-tab-view > .pane-frame,
.main-tab-view > .standalone-view {
  min-height: 0;
  height: 100%;
}

.pane-frame {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.pane-frame > .pane-header {
  min-height: var(--pane-header-height);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
}

.pane-body {
  min-height: 0;
  overflow: hidden;
  background: var(--surface);

