.context-language-select {
  max-width: 108px;
  cursor: pointer;
  padding: 0 22px 0 7px;
}

.context-live-toggle:hover,
.context-theme-toggle:hover {
  border-color: var(--accent-border);
  color: var(--accent);
}

.main-tab-view,
.dashboard-view {
  padding: var(--space-3);
}

.main-tab-view {
  padding-top: var(--space-3);
}

.app-context-bar-compact {
  margin-bottom: var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
}

@media (max-width: 720px) {
  .app-context-identity span,
  .app-context-status .status-badge {
    display: none;
  }

  font-size: var(--font-size-xs);
}

.dashboard-toolbar {
  margin: 0;
}

/* A tab and a dashboard cell share the same flat header/body boundary. */
.main-tab-view {
  min-height: 0;
  height: 100%;
  padding: var(--space-3);
  overflow: hidden;
}

.main-tab-view > .pane-frame,
.main-tab-view > .standalone-view {
  min-height: 0;
  height: 100%;
}

.pane-frame {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.pane-frame > .pane-header {
  min-height: var(--pane-header-height);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
