.app-shell { min-height: 100vh; padding: 0; }
.loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: grid;
  place-items: center;
  background: var(--overlay-bg);
  backdrop-filter: blur(10px);
}
.loading-card {
  display: grid;
  gap: 8px;
  min-width: 240px;
  padding: 20px 24px;
  border: 1px solid rgba(102, 217, 239, .22);
/*  border-radius: 18px;*/
  border-radius: 8px;
  background: rgba(10, 18, 27, .96);
  box-shadow: 0 18px 48px rgba(0, 0, 0, .34);
  text-align: center;
}
.loading-label {
  color: var(--text-strong);
  font-size: 18px;
  font-weight: 800;
  letter-spacing: .04em;
}
.loading-subtext {
  color: var(--muted);
  font-size: 12px;
}
