  overflow: hidden;
}
.menu-rail {
  position: sticky;
  top: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 14px;
  min-height: 100vh;
/*  padding: 14px 10px;*/
  padding: 10px 10px;
  border-right: 1px solid var(--line);
  border-radius: 0;
  background:
