.menu-rail-toggle-icon {
  display: grid;
  place-items: center;
  width: 20px;
  color: var(--accent);
  font-size: 16px;
  line-height: 1;
}
.menu-rail-brand {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.menu-rail-nav {
  display: grid;
  gap: 8px;
  align-content: start;
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 48px;
  padding: 0 10px;
  border: 1px solid transparent;
/*  border-radius: 10px;*/
/*  border-radius: 4px;*/
  border-radius: 3px;
  background: transparent;
  color: var(--muted);
  text-align: left;
  cursor: pointer;
}
.menu-item:hover,
.menu-item.active {
  background: rgba(102,217,239,.08);
  border-color: rgba(102,217,239,.16);
  color: #eef4fb;
