* { box-sizing: border-box; }
html, body, #root {
  overscroll-behavior-x: none;
}
body { margin: 0; min-width: 320px; background: var(--bg-main); color: var(--text-strong); }
body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
}
/*button, input { font: inherit; }*/
button, input {
	font: inherit;
	font-size: 18px;
}

.app-shell { min-height: 100vh; padding: 0; }
.loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: grid;
  place-items: center;
  background: var(--overlay-bg);
  backdrop-filter: blur(10px);
}
.loading-card {
  display: grid;
  gap: 8px;
  min-width: 240px;
  padding: 20px 24px;
  border: 1px solid rgba(102, 217, 239, .22);
/*  border-radius: 18px;*/
  border-radius: 8px;
  background: rgba(10, 18, 27, .96);
  box-shadow: 0 18px 48px rgba(0, 0, 0, .34);
  text-align: center;
}
.loading-label {
  color: var(--text-strong);
  font-size: 18px;
  font-weight: 800;
  letter-spacing: .04em;
}
.loading-subtext {
  color: var(--muted);
  font-size: 12px;
}
.app-frame { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 0; align-items: start; min-height: 100vh; }
.app-main {
  min-width: 0;
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
/*  padding: 18px 18px 18px 16px; */
  overflow: hidden;
}
.menu-rail {
  position: sticky;
  top: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 14px;
  min-height: 100vh;
/*  padding: 14px 10px;*/
  padding: 10px 10px;
  border-right: 1px solid var(--line);
  border-radius: 0;
  background:
    radial-gradient(circle at 50% 0%, rgba(102,217,239,.14), transparent 32%),
    linear-gradient(180deg, rgba(12, 23, 34, .96), rgba(17, 24, 34, .88));
  box-shadow: 0 20px 64px rgba(0,0,0,.22);
  backdrop-filter: blur(18px);
  transition: width .18s ease, padding .18s ease;
}
.menu-rail.collapsed { width: 72px; }
.menu-rail.expanded { width: 220px; }
.menu-rail-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 42px;
  padding: 0 10px;
  border: 1px solid rgba(143, 164, 188, .18);
/*  border-radius: 10px;*/
/*  border-radius: 4px;*/
  border-radius: 3px;
  background: rgba(255,255,255,.03);
  color: var(--text-strong);
  cursor: pointer;
}
.menu-rail-toggle:hover { background: rgba(102,217,239,.08); border-color: rgba(102,217,239,.24); }
.menu-rail-toggle-icon {
  display: grid;
  place-items: center;
  width: 20px;
  color: var(--accent);
  font-size: 16px;
  line-height: 1;
}
.menu-rail-brand {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}
.menu-rail-nav {
  display: grid;
  gap: 8px;
  align-content: start;
}
.menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 48px;
  padding: 0 10px;
  border: 1px solid transparent;
/*  border-radius: 10px;*/
/*  border-radius: 4px;*/
  border-radius: 3px;
  background: transparent;
  color: var(--muted);
  text-align: left;
  cursor: pointer;
}
.menu-item:hover,
.menu-item.active {
  background: rgba(102,217,239,.08);
  border-color: rgba(102,217,239,.16);
  color: #eef4fb;
}
.menu-item-icon {
  display: grid;
  place-items: center;
  width: 20px;
  flex: 0 0 20px;
  color: var(--accent);
  font-size: 17px;
  line-height: 1;
}
.menu-item-copy strong {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: inherit;
}
.menu-item-copy small {
  display: block;
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
}
.hero-panel { display: flex; align-items: end; justify-content: space-between; gap: 18px; padding: 22px; border: 1px solid var(--line); border-radius: 28px; background: linear-gradient(135deg, rgba(14,29,43,.9), rgba(37,28,18,.72)); box-shadow: 0 20px 64px rgba(0,0,0,.28); }
.eyebrow { margin: 0 0 8px; color: var(--accent); text-transform: uppercase; letter-spacing: .16em; font-size: 12px; }
h1, h2, h3, p { margin-top: 0; }
h1 { margin-bottom: 0; font-size: clamp(30px, 5vw, 58px); line-height: .96; letter-spacing: -.05em; max-width: 740px; }
.summary-strip { display: grid; grid-template-columns: repeat(4, minmax(86px, 1fr)); gap: 10px; min-width: min(520px, 100%); }
/*.summary-card, .stat-card { border: 1px solid var(--line); border-radius: 18px; padding: 11px; background: rgba(255,255,255,.045); }*/
.summary-card, .stat-card { border: 1px solid var(--line); border-radius: 18px; padding: 8px; background: rgba(255,255,255,.045); }
.summary-card span, .stat-card span { display: block; color: var(--muted); font-size: 12px; }
.summary-card strong, .stat-card strong { display: block; margin-top: 4px; font-size: 18px; }
.workspace {
  display: grid;
  grid-template-columns: minmax(390px, 42vw) 1fr;
  gap: 14px;
  margin-top: 14px;
  align-items: stretch;
  min-height: 0;
  overflow: hidden;
}
.list-pane, .detail-pane { border: 1px solid var(--line); border-radius: 28px; background: var(--panel); backdrop-filter: blur(18px); min-height: 580px; overflow: hidden; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.list-pane.timeline-layout {
  height: 100%;
  min-height: 0;
}
/*.list-toolbar { display: grid; grid-template-columns: 1fr; gap: 10px; padding: 16px; border-bottom: 1px solid var(--line); }*/
.list-toolbar { display: grid; grid-template-columns: 1fr; gap: 10px; padding: 10px; border-bottom: 1px solid var(--line); min-width: 0; }
.list-toolbar-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; min-width: 0; }
.list-toolbar-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: flex-end; }
/*.list-toolbar h2 { margin-bottom: 4px; }*/
.list-toolbar h2 {
	margin-bottom: 4px;
	font-size: 18px;
}
