  const displayThresholds = useMemo(() => thresholds.map((threshold) => ({ ...threshold, value: threshold.value / displayScale.divisor })), [thresholds, displayScale]);
  const thresholdSignature = thresholds.map((threshold) => [threshold.id, threshold.metric, threshold.value, threshold.severity, threshold.recovery, threshold.operator].join(":" )).join("|");
  const scaleSignature = [displayScale.divisor, displayScale.unit, yRange.min, yRange.max, yRange.splits.join(","), scalePreference].join("|");
  const theme = document.documentElement.dataset.theme ?? "light";

  useEffect(() => {
    if (!hostRef.current || !metric || metric.points.length === 0) return;

    const host = hostRef.current;
    hostVisibleRef.current = isVisibleInViewport(host);
    const styles = getComputedStyle(hostRef.current);
    const lineColor = resolveColor(hostRef.current, color, cssVar(styles, "--chart-accent", cssVar(styles, "--accent", "currentColor")));
    const axisColor = cssVar(styles, "--chart-axis", cssVar(styles, "--muted", "currentColor"));
    const gridColor = cssVar(styles, "--chart-grid", "transparent");
    const bandFill = toRgba(lineColor, compact ? 0.18 : 0.24);
    const rangeStroke = toRgba(lineColor, compact ? 0.28 : 0.34);
    const transparentStroke = toRgba(lineColor, 0);
    const labelBackground = toRgba(cssVar(styles, "--surface", "#ffffff"), compact ? 0.82 : 0.9);
    const thresholdLabels: DrawThresholdLabel[] = displayThresholds.map((threshold) => ({
      ...threshold,
      color: resolveColor(host, thresholdColor(threshold.severity), lineColor)
    }));
    const chartHeight = chartHeightFor(hostRef.current, height, fillHeight);
    const chartWidth = Math.max(1, host.clientWidth || hostWidth || 640);
    const axisWidth = chartAxisWidth(chartWidth);
    const axisDigits = chartAxisFractionDigits(yRange.splits, displayScale, axisWidth);
    const thresholdSeries = displayThresholds.map((threshold) => ({
      label: threshold.label,
      stroke: resolveColor(hostRef.current!, thresholdColor(threshold.severity), lineColor),
      width: threshold.recovery ? 1 : 1.5,
      dash: threshold.recovery ? [5, 4] : undefined,
      points: { show: false }
    }));
    const options: uPlot.Options = {
      width: chartWidth,
      height: chartHeight,
      cursor: { sync: { key: syncKey } },
      scales: { x: { time: true }, y: { auto: false, range: () => [yRange.min, yRange.max] } },
      legend: { show: false },
      hooks: {
        draw: [(chart) => drawThresholdLabels(chart, thresholdLabels, displayScale.unit, labelBackground, compact)],
        setCursor: [(chart) => {
          if (chart.cursor.idx == null || !hostRef.current || !hostVisibleRef.current) {
            setCursorPoint(null);
            return;
          }
          const point = metric.points[chart.cursor.idx];
          if (!point) {
            setCursorPoint(null);
            return;
          }
          setCursorPoint(point);
        }]
      },
      axes: compact
        ? [
            { show: false },
            { show: false }
          ]
        : [
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, values: (_u, values) => values.map((v) => formatChartAxisTime(v)) },
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, size: axisWidth, splits: () => yRange.splits, values: (_u, values) => values.map((v) => formatMetricAxisValue(v, displayScale, axisDigits)) }
          ],
      series: [
        {},
        {
          label: "min",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        {
          label: "max",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        { label: "avg", stroke: lineColor, width: compact ? 1.3 : 2, points: { show: false } },
        ...thresholdSeries
      ],
      bands: hasRangeBand ? [{ series: [2, 1], fill: bandFill }] : [],
      padding: compact ? [6, 4, 4, 4] : undefined
    } as uPlot.Options;

    chartRef.current?.destroy();
    chartRef.current = new uPlot(options, toUplotData(metric, displayThresholds, displayScale.divisor), host);

    const resize = () => {
      if (hostRef.current && chartRef.current) {
        const width = Math.max(1, hostRef.current.clientWidth);
        setHostWidth((current) => current === width ? current : width);
        chartRef.current.setSize({
          width,
          height: chartHeightFor(hostRef.current, height, fillHeight)
        });
      }
    };
    const resizeObserver = new ResizeObserver(() => resize());
    resizeObserver.observe(host);
    const visibilityObserver = new IntersectionObserver(([entry]) => {
      hostVisibleRef.current = entry.isIntersecting;
      if (!hostVisibleRef.current) setCursorPoint(null);
    });
    visibilityObserver.observe(host);
    window.addEventListener("resize", resize);
    return () => {
      resizeObserver.disconnect();
      visibilityObserver.disconnect();
      window.removeEventListener("resize", resize);
      chartRef.current?.destroy();
      chartRef.current = null;
    };
  }, [metric?.key, hasData, hasRangeBand, height, color, compact, fillHeight, thresholdSignature, scaleSignature, scalePreference, theme, hostWidth]);

  useEffect(() => {
    if (!chartRef.current || !metric || metric.points.length === 0) return;
    chartRef.current.setData(toUplotData(metric, displayThresholds, displayScale.divisor));
  }, [metric, thresholdSignature, scaleSignature, scalePreference]);

  return (
    <section className={`chart-card ${compact ? "compact-chart" : ""}`}>
      <div className="chart-header">
        <h3>{title}</h3>
        <div className="chart-header-meta">
          <div className={"chart-header-values " + (cursorPoint ? "is-active" : "is-idle")} aria-hidden="true">
            {!compact && <strong>{cursorPoint ? formatChartTime(cursorPoint.time) : "\u00a0"}</strong>}
