    const options: uPlot.Options = {
      width: chartWidth,
      height: chartHeight,
      cursor: { sync: { key: syncKey } },
      scales: { x: { time: true }, y: { auto: false, range: () => [yRange.min, yRange.max] } },
      legend: { show: false },
      hooks: {
        draw: [(chart) => drawThresholdLabels(chart, thresholdLabels, displayScale.unit, labelBackground, compact)],
        setCursor: [(chart) => {
          if (chart.cursor.idx == null || !hostRef.current || !hostVisibleRef.current) {
            setCursorPoint(null);
            return;
          }
          const point = metric.points[chart.cursor.idx];
          if (!point) {
            setCursorPoint(null);
            return;
          }
          setCursorPoint(point);
        }]
      },
      axes: compact
        ? [
            { show: false },
            { show: false }
          ]
        : [
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, values: (_u, values) => values.map((v) => formatChartAxisTime(v)) },
            { stroke: axisColor, grid: { stroke: gridColor }, ticks: { stroke: axisColor }, size: axisWidth, splits: () => yRange.splits, values: (_u, values) => values.map((v) => formatMetricAxisValue(v, displayScale, axisDigits)) }
          ],
      series: [
        {},
        {
          label: "min",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        {
          label: "max",
          stroke: hasRangeBand ? rangeStroke : transparentStroke,
          width: hasRangeBand ? 1 : 0,
          points: { show: false }
        },
        { label: "avg", stroke: lineColor, width: compact ? 1.3 : 2, points: { show: false } },
        ...thresholdSeries
      ],
      bands: hasRangeBand ? [{ series: [2, 1], fill: bandFill }] : [],
      padding: compact ? [6, 4, 4, 4] : undefined
    } as uPlot.Options;

    chartRef.current?.destroy();
    chartRef.current = new uPlot(options, toUplotData(metric, displayThresholds, displayScale.divisor), host);

    const resize = () => {
      if (hostRef.current && chartRef.current) {
        const width = Math.max(1, hostRef.current.clientWidth);
        setHostWidth((current) => current === width ? current : width);
        chartRef.current.setSize({
          width,
          height: chartHeightFor(hostRef.current, height, fillHeight)
        });
      }
    };
    const resizeObserver = new ResizeObserver(() => resize());
    resizeObserver.observe(host);
    const visibilityObserver = new IntersectionObserver(([entry]) => {
      hostVisibleRef.current = entry.isIntersecting;
      if (!hostVisibleRef.current) setCursorPoint(null);
    });
    visibilityObserver.observe(host);
    window.addEventListener("resize", resize);
    return () => {
      resizeObserver.disconnect();
      visibilityObserver.disconnect();
      window.removeEventListener("resize", resize);
      chartRef.current?.destroy();
      chartRef.current = null;
    };
  }, [metric?.key, hasData, hasRangeBand, height, color, compact, fillHeight, thresholdSignature, scaleSignature, scalePreference, theme, hostWidth]);

  useEffect(() => {
    if (!chartRef.current || !metric || metric.points.length === 0) return;
    chartRef.current.setData(toUplotData(metric, displayThresholds, displayScale.divisor));
  }, [metric, thresholdSignature, scaleSignature, scalePreference]);

  return (
    <section className={`chart-card ${compact ? "compact-chart" : ""}`}>
      <div className="chart-header">
        <h3>{title}</h3>
        <div className="chart-header-meta">
          <div className={"chart-header-values " + (cursorPoint ? "is-active" : "is-idle")} aria-hidden="true">
            {!compact && <strong>{cursorPoint ? formatChartTime(cursorPoint.time) : "\u00a0"}</strong>}
            {!compact && <span>min <b>{cursorPoint ? formatChartValue(cursorPoint.min ?? cursorPoint.avg ?? cursorPoint.value, displayScale, false) : "—"}</b></span>}
            <span>avg <b>{cursorPoint ? formatChartValue(cursorPoint.avg ?? cursorPoint.value, displayScale, compact) : "—"}</b></span>
            {!compact && <span>max <b>{cursorPoint ? formatChartValue(cursorPoint.max ?? cursorPoint.avg ?? cursorPoint.value, displayScale, false) : "—"}</b></span>}
          </div>
          {!compact && <span className="chart-header-unit">{displayScale.unit}</span>}
        </div>
      </div>
      <div
        className={`chart-host ${compact ? "compact-grid-host" : ""}`}
        ref={hostRef}
        style={{ minHeight: fillHeight ? 0 : height }}
      />
      {!hasData && <div className="empty-chart chart-empty-overlay">No data</div>}
    </section>
  );
}

function thresholdsForMetric(metric: TimeSeriesMetric | undefined, context: ChartAlertContext | undefined): ChartThreshold[] {
  if (!metric || !context) return [];
  return context.rules.flatMap((rule) => {
    if (rule.enabled === false || (rule.type ?? "threshold") !== "threshold") return [];
    const target = rule.target ?? "any";
    if (target !== "any" && target !== context.target) return [];
    if (context.proto && rule.proto && rule.proto !== context.proto) return [];
    if (metricKeyForAlert(rule.metric) !== metric.key || !Number.isFinite(rule.error_threshold)) return [];
    const severity = rule.severity ?? "warning";
    const operator = rule.operator ?? ">";
    const result: ChartThreshold[] = [{ id: rule.id, metric: rule.metric, operator, label: `${rule.id} trigger`, value: rule.error_threshold!, severity, recovery: false }];
    if (Number.isFinite(rule.recover_threshold) && Math.abs(rule.recover_threshold! - rule.error_threshold!) > Number.EPSILON) {
      result.push({ id: rule.id + ":recovery", metric: rule.metric, operator, label: `${rule.id} recovery`, value: rule.recover_threshold!, severity, recovery: true });
    }
    return result;
  });
}

function metricKeyForAlert(key: string) {
  const parts = key.split(".");
  return chartMetricValueFields.has(parts.at(-1) ?? "") ? parts.slice(0, -1).join(".") : key;
}

function thresholdColor(severity: string) {
  if (severity === "critical" || severity === "error") return "var(--error)";
  if (severity === "warning") return "var(--warning)";
  return "var(--accent)";
}

function drawThresholdLabels(chart: uPlot, thresholds: DrawThresholdLabel[], unit: string | undefined, background: string, compact: boolean) {
  if (thresholds.length === 0) return;
  const ratio = uPlot.pxRatio;
  const fontSize = (compact ? 9 : 10) * ratio;
  const labelHeight = (compact ? 13 : 16) * ratio;
  const gap = 3 * ratio;
  const padding = 4 * ratio;
  const { left, top, width, height } = chart.bbox;
  const entries = thresholds
    .map((threshold) => ({
      threshold,
      text: threshold.metric + " " + (threshold.recovery ? "recovery" : threshold.operator) + " " + formatFixedNumber(threshold.value) + (unit ? " " + unit : ""),
      y: chart.valToPos(threshold.value, "y", true)
    }))
    .filter((entry) => entry.y >= top && entry.y <= top + height)
    .sort((a, b) => a.y - b.y);
  if (entries.length === 0) return;

  const minY = top + labelHeight / 2;
  const maxY = top + height - labelHeight / 2;
  let previousY = minY - labelHeight - gap;
  const placed = entries.map((entry) => {
    const y = Math.max(minY, entry.y, previousY + labelHeight + gap);
    previousY = y;
    return { ...entry, y };
  });
  const overflow = placed[placed.length - 1].y - maxY;
  if (overflow > 0) placed.forEach((entry) => { entry.y -= overflow; });

  const context = chart.ctx;
  context.save();
  context.font = fontSize + "px system-ui, -apple-system, BlinkMacSystemFont, sans-serif";
  context.textAlign = "right";
  context.textBaseline = "middle";
  for (const entry of placed) {
    const textWidth = context.measureText(entry.text).width;
    const x = left + width - padding;
    context.fillStyle = background;
    context.fillRect(x - textWidth - padding, entry.y - labelHeight / 2, textWidth + padding * 2, labelHeight);
    context.fillStyle = entry.threshold.color;
    context.fillText(entry.text, x, entry.y);
  }
  context.restore();
}
  const grid = input.grid ?? {};
  const w = clampInt(grid.w, 2, columns, 6);
  const x = clampInt(grid.x, 0, Math.max(0, columns - w), 0);
  return {
    id: String(input.id ?? `cell-${index + 1}`),
    title: String(input.title ?? viewType),
    titleKey: typeof input.titleKey === "string" ? input.titleKey : undefined,
    viewType: viewType as DashboardLayout["cells"][number]["viewType"],
    grid: {
      x,
      y: clampInt(grid.y, 0, 200, index * 8),
      w,
      h: clampInt(grid.h, 3, 40, 8)
    },
    params: input.params && typeof input.params === "object" ? input.params : undefined
  };
}

