const DEFAULT_INSPECTOR_LAYOUT = DEFAULT_INSPECTOR_LAYOUTS[0];

function withInspectorTargetLayouts(layouts: InspectorLayout[]) {
  const kinds = new Set(layouts.map((layout) => layout.targetKind));
  return [...layouts, ...DEFAULT_INSPECTOR_LAYOUTS.filter((layout) => !kinds.has(layout.targetKind))];
}

async function readInspectorLayouts(): Promise<InspectorLayout[]> {
  if (!existsSync(config.inspectorLayoutsFile)) return DEFAULT_INSPECTOR_LAYOUTS;
  try {
    const parsed = JSON.parse(await readFile(config.inspectorLayoutsFile, "utf8")) as unknown;
    if (!Array.isArray(parsed)) return DEFAULT_INSPECTOR_LAYOUTS;
    const layouts = parsed.map(normalizeInspectorLayout).filter(Boolean) as InspectorLayout[];
    return withInspectorTargetLayouts(layouts.length > 0 ? layouts : [DEFAULT_INSPECTOR_LAYOUT]);
  } catch {
    return DEFAULT_INSPECTOR_LAYOUTS;
  }
}

async function writeInspectorLayouts(layouts: InspectorLayout[]) {
  await writeFile(config.inspectorLayoutsFile, JSON.stringify(layouts.map(normalizeInspectorLayout).filter(Boolean), null, 2) + "\n", "utf8");
}

function normalizeInspectorLayout(input: any): InspectorLayout | undefined {
  if (!input || typeof input !== "object") return undefined;
  const id = String(input.id ?? "default");
  const targetKind = input.targetKind === "interface" || input.targetKind === "flow" ? input.targetKind : "stream";
  const columns = clampInt(input.columns, 6, 48, 24);
  const cells = Array.isArray(input.cells) ? input.cells.map((cell: any, index: number) => normalizeInspectorCell(cell, index, columns, targetKind)).filter(Boolean) : [];
  const responsiveColumns = { desktop: 24, tablet: 12, mobile: 4 } as const;
  const layouts: NonNullable<InspectorLayout["layouts"]> = {};
  if (input.layouts && typeof input.layouts === "object") {
    for (const breakpoint of ["desktop", "tablet", "mobile"] as const) {
      const rawCells = input.layouts[breakpoint];
      if (!Array.isArray(rawCells)) continue;
      const normalized = rawCells.map((cell: any, index: number) => normalizeInspectorCell(cell, index, responsiveColumns[breakpoint], targetKind)).filter(Boolean);
      if (normalized.length > 0) layouts[breakpoint] = normalized as InspectorLayout["cells"];
    }
  }
  const activeCells = layouts.desktop ?? cells;
  if (activeCells.length === 0) return undefined;
  const layout: InspectorLayout = {
    id,
    name: String(input.name ?? id),
    targetKind,
    columns,
    rowHeight: clampInt(input.rowHeight, 20, 80, 32),
    cells: activeCells as InspectorLayout["cells"],
    layouts: Object.keys(layouts).length > 0 ? layouts : undefined
  };
  return targetKind === "interface" && id === "default-interface" ? upgradeDefaultInterfaceInspectorLayout(layout) : layout;
}

function normalizeInspectorCell(input: any, index: number, columns: number, targetKind: InspectorTargetKind): InspectorLayout["cells"][number] | undefined {
  if (!input || typeof input !== "object") return undefined;
  let type = String(input.type ?? "summary");
  if (!["summary", "stream-bitrate", "selected-flow-summary", "flows-table", "metric-chart", "metric-group", "all-flow-chart-group", "interface-bandwidth"].includes(type)) return undefined;
  const params = input.params && typeof input.params === "object" && !Array.isArray(input.params) ? { ...input.params } : undefined;
  const metricKey = typeof params?.metricKey === "string" ? params.metricKey : undefined;
  const legacyDirectionMetric = targetKind === "interface" && type === "interface-bandwidth" && (metricKey === "rx.bitrate" || metricKey === "tx.bitrate");
  if (legacyDirectionMetric) type = "metric-chart";
  else if (type !== "metric-chart" && params) delete params.metricKey;
  const grid = input.grid ?? {};
  const w = clampInt(grid.w, 2, columns, 6);
  return {
    id: String(input.id ?? "inspector-cell-" + (index + 1)),
    title: legacyDirectionMetric && String(input.title ?? "") === "Link Capacity" ? metricKey === "tx.bitrate" ? "TX Bitrate" : "RX Bitrate" : String(input.title ?? type),
    type: type as InspectorLayout["cells"][number]["type"],
    grid: { x: clampInt(grid.x, 0, Math.max(0, columns - w), 0), y: clampInt(grid.y, 0, 200, index * 8), w, h: clampInt(grid.h, 3, 40, 8) },
    params: params && Object.keys(params).length > 0 ? params : undefined
  };
}

function upgradeDefaultInterfaceInspectorLayout(layout: InspectorLayout): InspectorLayout {
  const upgradeCells = (cells: InspectorLayout["cells"], columns: number) => {
    const bandwidth = cells.find((cell) => cell.id === "bandwidth" && cell.type === "interface-bandwidth");
    let next = cells;
    if (bandwidth && bandwidth.grid.h < 6) {
      const delta = 6 - bandwidth.grid.h;
      const followingY = bandwidth.grid.y + bandwidth.grid.h;
      next = cells.map((cell) => cell.id === bandwidth.id
        ? { ...cell, grid: { ...cell.grid, h: 6 } }
        : cell.grid.y >= followingY ? { ...cell, grid: { ...cell.grid, y: cell.grid.y + delta } } : cell);
    }
    if (!next.some((cell) => cell.type === "metric-chart" && cell.params?.metricKey === "tx.bitrate")) {
      const y = next.reduce((max, cell) => Math.max(max, cell.grid.y + cell.grid.h), 0);
      next = [...next, { id: "tx-bitrate", title: "TX Bitrate", type: "metric-chart", grid: { x: 0, y, w: columns, h: 8 }, params: { metricKey: "tx.bitrate" } }];
    }
    return next;
  };
  const responsive = layout.layouts ? {
    desktop: layout.layouts.desktop ? upgradeCells(layout.layouts.desktop, 24) : undefined,
    tablet: layout.layouts.tablet ? upgradeCells(layout.layouts.tablet, 12) : undefined,
    mobile: layout.layouts.mobile ? upgradeCells(layout.layouts.mobile, 4) : undefined
  } : undefined;
  const cells = responsive?.desktop ?? upgradeCells(layout.cells, layout.columns);
  return { ...layout, cells, layouts: responsive };
}

function clampInt(value: unknown, min: number, max: number, fallback: number) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) return fallback;
  return Math.max(min, Math.min(max, Math.round(numberValue)));
}
