  overflow: hidden;
}
.bandwidth-gauge { width: 100%; max-height: 78px; overflow: visible; }
.bandwidth-gauge-track,
.bandwidth-gauge-value {
  fill: none;
  stroke-width: 10;
  stroke-linecap: round;
}
.bandwidth-gauge-track { stroke: rgba(143,164,188,.23); }
.bandwidth-gauge-value { stroke: var(--gauge-color); }
.bandwidth-gauge.unknown .bandwidth-gauge-track { stroke-dasharray: 4 5; }
.bandwidth-gauge-center {
  position: absolute;
  left: 10px;
  right: 10px;
  top: 40px;
  text-align: center;
  pointer-events: none;
}
.bandwidth-gauge-center strong {
  display: block;
  color: #eef4fb;
  font-size: 20px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.bandwidth-gauge-center span {
