.bandwidth-panel {
  margin-bottom: 12px;
  padding: 12px;
  border: 1px solid rgba(102,217,239,.16);
  border-radius: 12px;
  background:
    radial-gradient(circle at 12% 0%, rgba(102,217,239,.11), transparent 34%),
    rgba(255,255,255,.028);
}
.bandwidth-panel.compact { margin-bottom: 8px; padding: 10px; }
.bandwidth-panel-header {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: baseline;
  margin-bottom: 10px;
}
.bandwidth-panel-header h3 { margin: 0; font-size: 13px; color: #e9f2fa; }
.bandwidth-panel-header span { color: var(--muted); font-size: 11px; }
.bandwidth-gauge-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.bandwidth-gauge-card {
  --gauge-color: #66d9ef;
  position: relative;
  min-height: 124px;
  padding: 8px 10px 10px;
  border: 1px solid rgba(143,164,188,.16);
  border-radius: 11px;
  background: rgba(5,10,18,.22);
  overflow: hidden;
}
.bandwidth-gauge { width: 100%; max-height: 78px; overflow: visible; }
.bandwidth-gauge-track,
.bandwidth-gauge-value {
  fill: none;
  stroke-width: 10;
  stroke-linecap: round;
}
.bandwidth-gauge-track { stroke: rgba(143,164,188,.23); }
.bandwidth-gauge-value { stroke: var(--gauge-color); }
.bandwidth-gauge.unknown .bandwidth-gauge-track { stroke-dasharray: 4 5; }
.bandwidth-gauge-center {
  position: absolute;
  left: 10px;
  right: 10px;
  top: 40px;
  text-align: center;
  pointer-events: none;
}
.bandwidth-gauge-center strong {
  display: block;
  color: #eef4fb;
  font-size: 20px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.bandwidth-gauge-center span {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}
