    return () => {
      resizeObserver.disconnect();
      visibilityObserver.disconnect();
      window.removeEventListener("resize", resize);
      chartRef.current?.destroy();
      chartRef.current = null;
    };
  }, [metric?.key, hasData, hasRangeBand, height, color, compact, fillHeight, thresholdSignature, scaleSignature, scalePreference, theme, hostWidth]);

  useEffect(() => {
    if (!chartRef.current || !metric || metric.points.length === 0) return;
    chartRef.current.setData(toUplotData(metric, displayThresholds, displayScale.divisor));
  }, [metric, thresholdSignature, scaleSignature, scalePreference]);

  return (
    <section className={`chart-card ${compact ? "compact-chart" : ""}`}>
      <div className="chart-header">
        <h3>{title}</h3>
        <div className="chart-header-meta">
          <div className={"chart-header-values " + (cursorPoint ? "is-active" : "is-idle")} aria-hidden="true">
            {!compact && <strong>{cursorPoint ? formatChartTime(cursorPoint.time) : "\u00a0"}</strong>}
            {!compact && <span>min <b>{cursorPoint ? formatChartValue(cursorPoint.min ?? cursorPoint.avg ?? cursorPoint.value, displayScale, false) : "—"}</b></span>}
