public:
    struct result {
        std::uint64_t window{0};
        std::uint64_t total{0};
    };

public:
    void reset() {
        reset_window();
    }

    void reset_window() {
        window_ = 0;
    }

    void reset_all() {
        window_ = 0;
        total_ = 0;
    }

    void inc() {
        add(static_cast<std::uint64_t>(1));
    }

    void add(std::uint64_t n) {
        window_ += n;
        total_ += n;
    }

    void add(bool cond) {
        if (cond) {
            inc();
        }
    }

    bool empty() const {
        return window_ == 0;
    }

    std::uint64_t count() const {
        return window_;
    }

    std::uint64_t total() const {
        return total_;
    }

    result value() const {
        return result{ .window = window_, .total = total_ };
    }

private:
    std::uint64_t window_{0};
    std::uint64_t total_{0};
};

