json metric_sample_projector::make_sample(double now,
                                          const json &entry,
                                          bool is_interface,
                                          const json &source_record) const {
	const auto target = make_target(entry, is_interface);
	const auto source_id = source_record.value("record_id", std::string{});
	return json{
		{"schema_version", 3},
		{"record_type", "metric_sample"},
		{"record_id", source_id + ":sample:" + target.value("key", std::string{})},
		{"source_record_id", source_id},
		{"capture_id", source_record.value("capture_id", std::string{})},
		{"time", now},
		{"resolution_sec", 1},
		{"target", target},
		{"metrics", entry},
	};
}

void metric_sample_projector::append_entries(double now,
                                              const json::array_t &entries,
                                              bool is_interface,
                                              const json &source_record) {
	for(const auto &entry : entries) {
		if(!entry.is_object()) continue;
		auto sample = make_sample(now, entry, is_interface, source_record);
		m_samples_1s_writer->dump_at(now, sample);
		update_rollup(sample);
	}
}

void metric_sample_projector::update_rollup(const json &sample) {
	const double time = sample.value("time", 0.0);
	const double bucket_start = minute_floor(time);
	if(!m_bucket.has_value()) {
		m_bucket = minute_bucket{.bucket_start = bucket_start, .bucket_end = bucket_start + 60.0, .subjects = {}};
	}
	else if(bucket_start != m_bucket->bucket_start) {
		flush_bucket();
		m_bucket = minute_bucket{.bucket_start = bucket_start, .bucket_end = bucket_start + 60.0, .subjects = {}};
	}
	observe_sample(sample);
}

void metric_sample_projector::observe_sample(const json &sample) {
	if(!m_bucket.has_value()) return;
	const auto target = sample.value("target", json::object());
	const auto key = target.value("key", std::string{});
	if(key.empty()) return;

	auto &acc = m_bucket->subjects[key];
	if(acc.target.is_null()) acc.target = target;
	const auto &metrics = sample.value("metrics", json::object());
	if(acc.template_metrics.is_null()) acc.template_metrics = make_template(metrics);
	acc.capture_id = sample.value("capture_id", std::string{});
	acc.source_record_id = sample.value("source_record_id", std::string{});

	std::map<std::string, double> values;
	collect_values("", metrics, values);
	for(const auto &[path, value] : values) {
		acc.stats_by_path[path].add(value);
		acc.last_by_path[path] = value;
	}
}

void metric_sample_projector::flush_bucket() {
	if(!m_bucket.has_value()) return;
	for(const auto &[key, acc] : m_bucket->subjects) {
		json rolled_metrics = acc.template_metrics.is_null() ? json::object() : acc.template_metrics;
		for(const auto &[path, stats] : acc.stats_by_path) {
			json stat{
				{"value", stats.avg()},
				{"avg", stats.avg()},
				{"min", stats.min},
				{"max", stats.max},
				{"count", stats.count},
			};
			if(const auto last = acc.last_by_path.find(path); last != acc.last_by_path.end()) stat["last"] = last->second;
			set_path(rolled_metrics, path, std::move(stat));
		}
		json sample{
			{"schema_version", 3},
			{"record_type", "metric_sample"},
			{"record_id", "rollup:" + std::to_string(static_cast<long long>(m_bucket->bucket_end)) + ":" + std::to_string(m_rollup_sequence++) + ":" + key},
			{"source_record_id", acc.source_record_id},
			{"capture_id", acc.capture_id},
			{"time", m_bucket->bucket_end},
			{"bucket_start", m_bucket->bucket_start},
			{"bucket_end", m_bucket->bucket_end},
			{"resolution_sec", 60},
			{"target", acc.target},
			{"metrics", std::move(rolled_metrics)},
		};
		m_samples_1m_writer->dump_at(m_bucket->bucket_end, sample);
	}
	m_bucket.reset();
}
