  if (cell.type === "metric-chart") { const chart = singleMetric(cell, visibleMetrics, sourceInterfaceMetrics, selectedFlowKey); return chart ? <MetricChart title={chart.metric.label} metric={chart.metric} color={chart.target === "interface" ? (chart.metric.key.startsWith("tx.") ? "var(--chart-tx)" : "var(--chart-rx)") : "var(--chart-metric-bitrate)"} fillHeight yScale={yScale} scalePreference={scalePreference} alertContext={chart.target === "interface" ? interfaceContext : flowContext} /> : <Unavailable message="Choose a metric" />; }
  if (cell.type === "metric-group") { const category = categoryFor(cell); const descriptors = visibleMetrics?.descriptors.filter((descriptor) => descriptor.category === category).slice(0, 8) ?? []; return descriptors.length ? <div className="inspector-metric-group">{descriptors.map((descriptor) => <MetricGroup key={descriptor.key} descriptor={descriptor} metrics={visibleMetrics!} context={flowContext} yScale={yScale} scalePreference={scalePreference} />)}</div> : <Unavailable />; }
