/** Projects metrics-journal snapshots into target-addressable metric samples. */
class metric_sample_projector {
public:
	struct config {
		std::filesystem::path root_dir{"metrics"};
		std::filesystem::path samples_1s_dir{"samples/1s"};
		std::filesystem::path samples_1m_dir{"samples/1m"};
		std::uint64_t part_size_bytes{64ULL * 1024ULL * 1024ULL};
		std::uint32_t retention_hours{72U};
	};

	explicit metric_sample_projector(config cfg);
	~metric_sample_projector();

	void append_snapshot(double now,
	                     const json::array_t &metrics,
	                     const json::array_t &interfaces,
	                     const json &source_record);

private:
	struct subject_accumulator {
		json target;
		json template_metrics;
		std::map<std::string, metrics::value_stats> stats_by_path;
		std::map<std::string, double> last_by_path;
		std::set<std::string> interval_paths;
		std::string capture_id;
		std::string source_record_id;
	};

	struct minute_bucket {
		double bucket_start{0.0};
		double bucket_end{0.0};
		std::map<std::string, subject_accumulator> subjects;
	};

	config m_cfg;
	std::unique_ptr<time_rotating_writer> m_samples_1s_writer;
	std::unique_ptr<time_rotating_writer> m_samples_1m_writer;
	std::optional<minute_bucket> m_bucket;
	std::uint64_t m_rollup_sequence{0};

	static double minute_floor(double now);
	static std::string target_key(const json &entry, bool is_interface);
	static json make_target(const json &entry, bool is_interface);
	return out;
}

double metric_sample_projector::first_stat_value(const json &record) {
	static const char *keys[] = {"value", "bps", "pps", "seconds", "window", "total", "avg", "min", "max"};
	for(const char *key : keys) {
		if(record.contains(key) && record.at(key).is_number()) return record.at(key).get<double>();
	}
	return 0.0;
}

void metric_sample_projector::collect_values(const std::string &prefix,
                                             const json &value,
                                             std::map<std::string, double> &out,
                                             std::set<std::string> &interval_paths) {
	if(is_stat_object(value)) {
		out[prefix] = first_stat_value(value);
		if(value.contains("window") && value.at("window").is_number()) interval_paths.insert(prefix);
		return;
	}
	if(value.is_number()) {
		out[prefix] = value.get<double>();
		return;
	}
	if(!value.is_object() || value.is_array()) return;
	for(auto it = value.begin(); it != value.end(); ++it) {
		const auto child_prefix = prefix.empty() ? it.key() : prefix + "." + it.key();
		collect_values(child_prefix, it.value(), out, interval_paths);
	}
}


	auto &acc = m_bucket->subjects[key];
	if(acc.target.is_null()) acc.target = target;
	const auto &metrics = sample.value("metrics", json::object());
	if(acc.template_metrics.is_null()) acc.template_metrics = make_template(metrics);
	acc.capture_id = sample.value("capture_id", std::string{});
	acc.source_record_id = sample.value("source_record_id", std::string{});

	std::map<std::string, double> values;
	std::set<std::string> interval_paths;
	collect_values("", metrics, values, interval_paths);
	for(const auto &[path, value] : values) {
		acc.stats_by_path[path].add(value);
		acc.last_by_path[path] = value;
		if(interval_paths.contains(path)) acc.interval_paths.insert(path);
	}
}

void metric_sample_projector::flush_bucket() {
	if(!m_bucket.has_value()) return;
	for(const auto &[key, acc] : m_bucket->subjects) {
		json rolled_metrics = acc.template_metrics.is_null() ? json::object() : acc.template_metrics;
		for(const auto &[path, stats] : acc.stats_by_path) {
			const bool interval = acc.interval_paths.contains(path);
			json stat{
				{"value", interval ? stats.sum : stats.avg()},
				{"avg", stats.avg()},
				{"min", stats.min},
				{"max", stats.max},
				{"count", stats.count},
			};
			if(interval) stat["window"] = stats.sum;
			if(const auto last = acc.last_by_path.find(path); last != acc.last_by_path.end()) stat["last"] = last->second;
			set_path(rolled_metrics, path, std::move(stat));
		}

