#ifndef METRIC_SAMPLE_PROJECTOR_H
#define METRIC_SAMPLE_PROJECTOR_H

#include <cstdint>
#include <filesystem>
#include <map>
#include <memory>
#include <optional>
#include <string>
#include <set>

#include "json.h"
#include "metrics_common.h"
#include "writer.h"

/** Projects metrics-journal snapshots into target-addressable metric samples. */
class metric_sample_projector {
public:
	struct config {
		std::filesystem::path root_dir{"metrics"};
		std::filesystem::path samples_1s_dir{"samples/1s"};
		std::filesystem::path samples_1m_dir{"samples/1m"};
		std::uint64_t part_size_bytes{64ULL * 1024ULL * 1024ULL};
		std::uint32_t retention_hours{72U};
	};

	explicit metric_sample_projector(config cfg);
	~metric_sample_projector();

	void append_snapshot(double now,
	                     const json::array_t &metrics,
	                     const json::array_t &interfaces,
	                     const json &source_record);

private:
	struct subject_accumulator {
		json target;
		json template_metrics;
		std::map<std::string, metrics::value_stats> stats_by_path;
		std::map<std::string, double> last_by_path;
		std::set<std::string> interval_paths;
		std::string capture_id;
		std::string source_record_id;
	};

	struct minute_bucket {
		double bucket_start{0.0};
		double bucket_end{0.0};
		std::map<std::string, subject_accumulator> subjects;
	};

	config m_cfg;
	std::unique_ptr<time_rotating_writer> m_samples_1s_writer;
	std::unique_ptr<time_rotating_writer> m_samples_1m_writer;
	std::optional<minute_bucket> m_bucket;
	std::uint64_t m_rollup_sequence{0};

	static double minute_floor(double now);
	static std::string target_key(const json &entry, bool is_interface);
	static json make_target(const json &entry, bool is_interface);
	static bool is_stat_object(const json &value);
	static json make_template(const json &value);
	static double first_stat_value(const json &record);
	static void collect_values(const std::string &prefix, const json &value, std::map<std::string, double> &out, std::set<std::string> &interval_paths);
	static void set_path(json &out, const std::string &path, json value);

	json make_sample(double now, const json &entry, bool is_interface, const json &source_record) const;
	void append_entries(double now, const json::array_t &entries, bool is_interface, const json &source_record);
	void update_rollup(const json &sample);
	void observe_sample(const json &sample);
	void flush_bucket();
};

#endif /* METRIC_SAMPLE_PROJECTOR_H */
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://stm.local/schema/metric-sample.schema.json",
  "title": "STM projected metric sample",
  "description": "One target-addressable metric sample. Resolution 1 is a journal-derived observation; larger resolutions are projector rollups.",
  "type": "object",
  "required": [
    "schema_version",
    "record_type",
    "record_id",
    "time",
    "resolution_sec",
    "target",
    "metrics"
  ],
  "properties": {
    "schema_version": {"const": 3},
    "record_type": {"const": "metric_sample"},
    "record_id": {"type": "string"},
    "source_record_id": {"type": "string"},
    "capture_id": {"type": "string"},
    "time": {
      "type": "number",
      "description": "Sample time or rollup bucket end as Unix epoch seconds.",
      "x-unit": "s"
    },
    "resolution_sec": {
      "type": "number",
      "minimum": 1,
      "description": "Sampling or aggregation resolution.",
      "x-unit": "s"
    },
    "bucket_start": {"type": "number", "x-unit": "s"},
    "bucket_end": {"type": "number", "x-unit": "s"},
    "target": {
      "type": "object",
      "required": ["kind", "key", "scope"],
      "properties": {
        "kind": {"enum": ["stream", "flow", "interface"]},
        "key": {"type": "string", "description": "Stable target identity."},
        "stream_key": {"type": "string"},
        "flow_key": {"type": "string"},
        "interface_id": {"type": "integer"},
        "interface_name": {"type": "string"},
        "proto": {"type": "string"},
        "role": {"type": "string"},
        "endpoint": {"type": "object"},
        "scope": {"type": "object"},
        "link": {"type": "object"}
      },
      "allOf": [
        {
          "if": {"properties": {"kind": {"const": "flow"}}},
          "then": {"required": ["stream_key", "flow_key"]}
        },
        {
          "if": {"properties": {"kind": {"const": "stream"}}},
          "then": {"required": ["stream_key"]}
        },
        {
          "if": {"properties": {"kind": {"const": "interface"}}},
          "then": {"anyOf": [{"required": ["interface_id"]}, {"required": ["interface_name"]}]}
        }
      ],
      "additionalProperties": true
    },
    "metrics": {
      "type": "object",
      "description": "Protocol- or interface-specific metric payload. Numeric values use their metric-specific units. Resolution 60 values may include value, avg, min, max, count, and last."
    }
  },
  "additionalProperties": true
}
