const snapIntervalCursor: uPlot.Cursor.MousePosRefiner = (chart, mouseLeft, mouseTop) => {
  const times = chart.data[0] as number[];
  const index = intervalIndexAtTime(times, chart.posToVal(mouseLeft, "x"));
  if (index == null) return [mouseLeft, mouseTop];
  const center = (intervalStartTime(times, index) + times[index]) / 2;
  return [chart.valToPos(center, "x"), mouseTop];
};

const intervalCursorDataIndex: uPlot.Cursor.DataIdxRefiner = (chart, _seriesIdx, _closestIdx, time) => intervalIndexAtTime(chart.data[0] as number[], time);

function intervalIndexAtTime(times: number[], time: number) {
  if (!Number.isFinite(time) || times.length === 0) return null;
  let low = 0;
  let high = times.length - 1;
  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if (times[middle] < time) low = middle + 1;
    else high = middle;
  }
  return low;
}

function intervalStartTime(times: number[], index: number) {
  const end = times[index];
  const next = times[index + 1] ?? end;
  return index > 0 ? times[index - 1] : end - Math.max(1, next - end);
}

