.stream-table {
  padding: var(--space-1);
  background: var(--surface);
}

.stream-table-virtual-item {
  padding-right: var(--space-1);
}

.stream-table-virtual-item-interface {
  border-bottom: 1px solid var(--line);
}

.stream-table-virtual-item-proto {
  padding-left: var(--space-2);
}

.stream-table-virtual-item-stream {
  padding-left: calc(var(--space-2) * 2);
}

.stream-table-virtual-flow {
  margin: 0;
  padding-left: calc(var(--space-2) * 3);
}

.interface-row,
.proto-row,
.stream-row,
.flow-list-row {
  width: 100%;
  min-height: 36px;
  margin-left: 0;
  padding: 6px var(--space-2);
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text);
}

.interface-row {
  background: var(--surface-muted);
}

.proto-row {
  min-height: 34px;
}

.stream-row,
.flow-list-row {
  grid-template-columns: 18px 10px minmax(0, 1fr) minmax(190px, 230px);
}

.flow-list-row {
  grid-template-columns: 10px minmax(0, 1fr) minmax(190px, 230px);
}

.stream-title,
.flow-title,
.interface-title,
.proto-title {
  font-size: var(--font-size-sm);
}

.stream-subtitle,
.flow-subtitle,
.interface-subtitle,
.proto-title span {
  margin-top: 2px;
  font-size: var(--font-size-xs);
}

.stream-rate,
.interface-rate-value {
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  font-variant-numeric: tabular-nums;
}

.row-right {
  gap: var(--space-2);
}

.status-dot {
  width: 8px;
  height: 8px;
  box-shadow: none;
}

.tree-toggle.expandable {
  padding: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1;
}

.inline-copy-button {
  border-color: var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
  color: var(--muted);
}

.inline-copy-button:hover {
  border-color: var(--accent-border);
  background: var(--accent-soft);
  color: var(--accent);
}

@media (max-width: 900px) {
  .stream-row,
  .flow-list-row {
    grid-template-columns: 18px 10px minmax(0, 1fr);
  }

  .flow-list-row {
    grid-template-columns: 10px minmax(0, 1fr);
  }

  .stream-row-right,
  .flow-row-right,
  .interface-sparklines {
    display: none;
  }
}

