export function StreamTable({ streams, interfaces, selectedStreamKey, selectedFlowKey, selectedInterfaceKey, overviewMode = false, expandLevel = "flow", onSelectInterface, onSelectStream, onSelectFlow, onAddToDashboard, pickerMode = false }: StreamTableProps) {
