    });
  }, [expandLevel, groupedByInterface, interfaceGroups, streams]);

  useEffect(() => {
    if (!focusedStream || !focusRowKey) return;
    const interfaceGroup = groupedByInterface ? interfaceGroups.find((group) => group.streams.some((stream) => stream.streamKey === focusedStream.streamKey)) : undefined;
    const collection = interfaceGroup?.streams ?? streams;
    const parentKey = interfaceGroup?.key ?? "root";
    const scopeGroup = buildScopeGroups(collection, parentKey).find((group) => group.streams.some((stream) => stream.streamKey === focusedStream.streamKey));
    const protoGroup = scopeGroup ? buildProtoGroups(scopeGroup.streams, scopeGroup.key).find((group) => group.streams.some((stream) => stream.streamKey === focusedStream.streamKey)) : undefined;

    if (interfaceGroup) setExpandedInterfaces((current) => addSetValues(current, [interfaceGroup.key]));
    if (scopeGroup) setExpandedScopeGroups((current) => addSetValues(current, [scopeGroup.key]));
    if (protoGroup) setExpandedProtoGroups((current) => addSetValues(current, [protoGroup.key]));
    if (focusedFlowAvailable) setExpanded((current) => addSetValues(current, [focusedStream.streamKey]));
  }, [focusRowKey, focusedFlowAvailable, focusedStream, groupedByInterface, interfaceGroups, streams]);

  useLayoutEffect(() => {
    if (!ENABLE_FLIP_ANIMATION) {
