function OverviewStats({ stats }: { stats: StreamListItem["overview"] }) {
  const eventsAvailable = stats.eventsAvailable !== false;
  const counters = [
    { key: "gap", label: "Gap", value: stats.gap ?? 0, available: true },
    { key: "dup", label: "Dup", value: stats.dup ?? 0, available: true },
    { key: "reorder", label: "Re", value: stats.reorder ?? 0, available: true },
    { key: "events", label: "Ev", value: stats.events ?? 0, available: eventsAvailable }
  ];
  const packetErrorCount = counters.slice(0, 3).reduce((sum, counter) => sum + counter.value, 0);
  const compactLabel = packetErrorCount > 0 ? "Err" : "Ev";
  const compactCount = packetErrorCount > 0 ? packetErrorCount : (eventsAvailable ? stats.events ?? 0 : 0);
  const summary = counters.map((counter) => `${counter.label} ${counter.available ? formatExactCount(counter.value) : "—"}`).join(" · ");
  const previousCounts = useRef<Record<string, number> | undefined>(undefined);
  const [increasingKeys, setIncreasingKeys] = useState<string[]>([]);

  useEffect(() => {
    const currentCounts = Object.fromEntries(counters.map((counter) => [counter.key, counter.available ? counter.value : 0]));
    const previous = previousCounts.current;
    previousCounts.current = currentCounts;
    if (!previous) return;

    const increased = counters
      .filter((counter) => counter.available && counter.value > (previous[counter.key] ?? 0))
      .map((counter) => counter.key);
    if (increased.length === 0) return;

    setIncreasingKeys(increased);
    const timer = window.setTimeout(() => setIncreasingKeys([]), 600);
    return () => window.clearTimeout(timer);
  }, [stats.gap, stats.dup, stats.reorder, stats.events, eventsAvailable]);

  return (
    <span className="overview-stats" aria-label={`Overview counters: ${summary}`} title={summary}>
      <span className="overview-compact"><small>{compactLabel}</small><strong>{formatCount(compactCount)}</strong></span>
      {counters.map((counter) => (
        <span
          key={counter.key}
          className={["overview-counter", counter.available && counter.value > 0 ? "is-error" : "", increasingKeys.includes(counter.key) ? "is-increasing" : ""].filter(Boolean).join(" ")}
        >
          <small>{counter.label}</small>
          <strong className={counter.available ? undefined : "overview-value-unavailable"}>{counter.available ? formatCount(counter.value) : "—"}</strong>
        </span>
      ))}
    </span>
  );
}

function hasOverviewCounters(stats: StreamListItem["overview"]) {
