  --panel-strong: #ffffff;
  --line: #d8dee8;
  --line-strong: #c5cfdc;
  --muted: #66758a;
  --text: #17202a;
  --text-strong: #111827;
  --text-inverse: #f8fafc;
  --accent: #5b47d6;
  --accent-2: #0f8b8d;
  --accent-soft: rgba(91, 71, 214, .10);
  --accent-border: rgba(91, 71, 214, .28);
  --success: #0b8f55;
  --success-soft: rgba(11, 143, 85, .12);
  --danger: #c43d3d;
  --danger-soft: rgba(196, 61, 61, .12);
  --warning: #b7791f;
  --warning-soft: rgba(183, 121, 31, .12);
  --chart-grid: rgba(87, 102, 120, .16);
  --chart-axis: #778397;
  --chart-accent: #5b47d6;
  --chart-band: rgba(91, 71, 214, .16);
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, .06);
  --shadow-md: 0 10px 30px rgba(15, 23, 42, .08);
  --bg-main: linear-gradient(180deg, #f8fafc 0%, #eef2f7 100%);
  --overlay-bg: rgba(248, 250, 252, .74);
}

:root[data-theme="dark"] {
  color-scheme: dark;
  background: #101418;
  color: #e8edf4;
  --bg: #101418;
  --bg-subtle: #171d24;
  --surface: #171d24;
  --surface-raised: #1d2530;
  --surface-muted: #151a21;
  --panel: #171d24;
  --panel-strong: #1d2530;
  --line: #2c3644;
  --line-strong: #3a4656;
  --muted: #9aa7b7;
  --text: #e8edf4;
  --text-strong: #f5f7fb;
  --text-inverse: #111827;
  --accent: #8b7cf6;
  --accent-2: #31c5bd;
  --accent-soft: rgba(139, 124, 246, .16);
  --accent-border: rgba(139, 124, 246, .34);
  --success: #55d98f;
  --success-soft: rgba(85, 217, 143, .14);
  --danger: #ff7b72;
  --danger-soft: rgba(255, 123, 114, .16);
  --warning: #f0bd62;
  --warning-soft: rgba(240, 189, 98, .16);
  --chart-grid: rgba(154, 167, 183, .18);
  --chart-axis: #9aa7b7;
  --chart-accent: #8b7cf6;
  --chart-band: rgba(139, 124, 246, .18);
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, .18);
  --shadow-md: 0 16px 38px rgba(0, 0, 0, .28);
  --bg-main: linear-gradient(180deg, #101418 0%, #151a21 100%);
  --overlay-bg: rgba(9, 12, 16, .72);
}

* { box-sizing: border-box; }
html, body, #root {
  overscroll-behavior-x: none;
}
body { margin: 0; min-width: 320px; background: var(--bg-main); color: var(--text-strong); }
body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
}
/*button, input { font: inherit; }*/
button, input {
	font: inherit;
	font-size: 18px;
}

.app-shell { min-height: 100vh; padding: 0; }
.loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: grid;
  place-items: center;
  background: var(--overlay-bg);
  backdrop-filter: blur(10px);
}
.loading-card {
  display: grid;
  gap: 8px;
  min-width: 240px;
  padding: 20px 24px;
  border: 1px solid rgba(102, 217, 239, .22);
/*  border-radius: 18px;*/
  border-radius: 8px;
  background: rgba(10, 18, 27, .96);
  box-shadow: 0 18px 48px rgba(0, 0, 0, .34);
  text-align: center;
}
.loading-label {
  color: var(--text-strong);
  font-size: 18px;
  font-weight: 800;
  letter-spacing: .04em;
}
.loading-subtext {
  color: var(--muted);
  font-size: 12px;
