* { box-sizing: border-box; }
html, body, #root {
  overscroll-behavior-x: none;
}
body { margin: 0; min-width: 320px; background: var(--bg-main); color: var(--text-strong); }
body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
}
/*button, input { font: inherit; }*/
button, input {
	font: inherit;
	font-size: 18px;
}

.app-shell { min-height: 100vh; padding: 0; }
.loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: grid;
  place-items: center;
  background: var(--overlay-bg);
  backdrop-filter: blur(10px);
}
.loading-card {
  display: grid;
  gap: 8px;
  min-width: 240px;
  padding: 20px 24px;
  border: 1px solid rgba(102, 217, 239, .22);
/*  border-radius: 18px;*/
  border-radius: 8px;
  background: rgba(10, 18, 27, .96);
  box-shadow: 0 18px 48px rgba(0, 0, 0, .34);
  text-align: center;
}
.loading-label {
  color: var(--text-strong);
  font-size: 18px;
  font-weight: 800;
  letter-spacing: .04em;
}
.loading-subtext {
  color: var(--muted);
  font-size: 12px;
}
.app-frame { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 0; align-items: start; min-height: 100vh; }
.app-main {
  min-width: 0;
  min-height: 100vh;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
/*  padding: 18px 18px 18px 16px; */
  overflow: hidden;
}
.menu-rail {
  position: sticky;
  top: 0;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 14px;
  min-height: 100vh;
/*  padding: 14px 10px;*/
  padding: 10px 10px;
  border-right: 1px solid var(--line);
  border-radius: 0;
  background:
    radial-gradient(circle at 50% 0%, rgba(102,217,239,.14), transparent 32%),
    linear-gradient(180deg, rgba(12, 23, 34, .96), rgba(17, 24, 34, .88));
  box-shadow: 0 20px 64px rgba(0,0,0,.22);
  backdrop-filter: blur(18px);
  transition: width .18s ease, padding .18s ease;
}
.menu-rail.collapsed { width: 72px; }
.menu-rail.expanded { width: 220px; }
.menu-rail-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 42px;
  padding: 0 10px;
  border: 1px solid rgba(143, 164, 188, .18);
/*  border-radius: 10px;*/
/*  border-radius: 4px;*/
