item.stdout:
/* Shared metrics grid: keep all right-side metrics aligned regardless of tree depth. */
.stream-table-virtual-item,
.stream-table-virtual-flow {
  padding-left: 0;
}
.stream-table-virtual-item-interface { --stream-tree-indent: 0px; }
.stream-table-virtual-item-scope { --stream-tree-indent: 24px; }
.stream-table-virtual-item-proto { --stream-tree-indent: 48px; }
.stream-table-virtual-item-stream { --stream-tree-indent: 72px; }
.stream-table-virtual-item-flow { --stream-tree-indent: 96px; }
.stream-table .scope-row,
.stream-table .proto-row,
.stream-table .stream-row,
.stream-table .flow-list-row {
  box-sizing: border-box;
  width: 100%;
  padding-left: calc(8px + var(--stream-tree-indent, 0px));
  padding-right: 8px;
  grid-template-columns: 20px 10px minmax(0, 1fr) 64px var(--stream-overview-stats-width) 72px 150px 28px;
}
.stream-table .scope-row .proto-main,
.stream-table .proto-row .proto-main,
.stream-table .stream-row .stream-main,
.stream-table .flow-list-row .flow-main {
  grid-column: 3;
  min-width: 0;
}
.stream-table .flow-list-row > .status-dot { grid-column: 2; }
.stream-table .stream-last-seen { grid-column: 4; justify-self: end; min-width: 0; }
.stream-table .stream-errors-block { grid-column: 5; }
.stream-table .stream-traffic-block { grid-column: 6; justify-self: end; }
.stream-table .stream-trend-block { grid-column: 7; }
.stream-table .row-action-menu { grid-column: 8; }
.stream-table .stream-row-truncated .stream-main,
.stream-table .flow-list-row-truncated .flow-main { grid-column: 3; }

/* The rate and sparkline reserve the same columns on scope/protocol rows. */
.stream-table .scope-row .stream-traffic-block,
.stream-table .proto-row .stream-traffic-block { grid-column: 6; }
.stream-table .scope-row .stream-trend-block,
.stream-table .proto-row .stream-trend-block { grid-column: 7; }

@media (max-width: 900px) {
  .stream-table .scope-row,
  .stream-table .proto-row,
  .stream-table .stream-row,
            <div className="standalone-inspector-cell-body"><InspectorCellContent cell={linkedCell} stream={detailStreamForStandalone} metrics={selectedMetrics} selectedFlowKey={selectedFlowKey} interfaceItem={selectedInterfaceKey && !selectedStreamKey ? selectedInterface : null} interfaceMetrics={selectedInterfaceKey && !selectedStreamKey ? selectedInterfaceMetrics : null} alertRules={alertRules} /></div>
          </> : <div className="empty-chart">Inspector cell is no longer available.</div>}
        </section>}
      <InspectorTargetDrawer
        open={inspectorTargetPickerOpen}
        modal={false}
        streams={streams}
        interfaces={interfaces}
        selectedStreamKey={selectedStreamKey}
        selectedFlowKey={selectedFlowKey}
        selectedInterfaceKey={selectedInterfaceKey}
        onClose={() => setInspectorTargetPickerOpen(false)}
        onSelectInterface={(interfaceKey) => { selectInspectorInterface(interfaceKey); setInspectorTargetPickerOpen(false); }}
        onSelectStream={(streamKey) => {
          selectInspectorStream(streamKey);
        }}
        onSelectFlow={(streamKey, flowKey) => {
          selectInspectorFlow(streamKey, flowKey);
        }}
      />
      </main>
    );
  }

  return (
    <main className="app-shell" aria-busy={loading}>
      {loading && (
        <div className="loading-overlay" role="status" aria-live="polite" aria-label="Loading">
          <div className="loading-card">
            <span className="loading-label">{loadingLabel}</span>
            <span className="loading-subtext">{loadingSubtext}</span>
          </div>
        </div>
      )}
      <div className="app-frame">
        <aside className={`menu-rail ${menuExpanded ? "expanded" : "collapsed"}`}>
          <button
            type="button"
            className="menu-rail-toggle"
            onClick={() => setMenuExpanded((current) => !current)}
            aria-pressed={menuExpanded}
          </>}
        </div>}
      />
      <div className="dashboard-pane-body">
        <DashboardGrid
          dashboard={dashboardLayout}
          editing={dashboardEditing}
          editMode={appConfig.dashboardLayoutEditMode}
          renderCell={renderDashboardCellContent}
          renderCellActions={renderDashboardCellActions}
          onLayoutsChange={updateDashboardLayouts}
          onUpdateCell={updateDashboardCell}
          onRemoveCell={removeDashboardCell}
        />
      </div>
      <InspectorTargetDrawer
        open={dashboardTargetPicker !== null}
        modal
        streams={streams}
        interfaces={interfaces}
        selectedStreamKey={dashboardSelectedStreamKey}
        selectedFlowKey={dashboardSelectedFlowKey}
        selectedInterfaceKey={null}
        onClose={() => setDashboardTargetPicker(null)}
        onSelectInterface={() => undefined}
        onSelectStream={(streamKey) => {
          if (dashboardTargetPicker?.mode === "pinned") updateDashboardCellParams(dashboardTargetPicker.cellId, { detailTargetMode: "pinned", targetStreamKey: streamKey, targetFlowKey: "" });
          else selectDashboardStream(streamKey);
          setDashboardTargetPicker(null);
        }}
        onSelectFlow={(streamKey, flowKey) => {
          if (dashboardTargetPicker?.mode === "pinned") updateDashboardCellParams(dashboardTargetPicker.cellId, { detailTargetMode: "pinned", targetStreamKey: streamKey, targetFlowKey: flowKey });
          else selectDashboardFlow(streamKey, flowKey);
          setDashboardTargetPicker(null);
        }}
      />
    </section>
  );

