.inspector-target-drawer-backdrop {
  position: fixed;
  z-index: 40;
  inset: 0;
  display: flex;
  justify-content: flex-end;
  pointer-events: none;
  animation: dashboard-target-fade-in 140ms ease-out;
}

.inspector-target-drawer-backdrop.is-modal {
  pointer-events: auto;
  background: color-mix(in srgb, var(--bg) 38%, transparent);
}

.inspector-target-drawer {
  width: min(460px, 100vw);
  height: 100%;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  border-left: 1px solid var(--line);
  background: var(--surface);
  box-shadow: var(--shadow-lg);
  pointer-events: auto;
  animation: dashboard-target-slide-in 180ms ease-out;
}

.inspector-target-drawer-header {
  min-height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-bottom: 1px solid var(--line);
}

.inspector-target-drawer-header > div {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.inspector-target-drawer-header strong {
  color: var(--text-strong);
}

.inspector-target-drawer-header small {
  color: var(--text-muted);
}

.inspector-target-drawer-search {
  padding: var(--space-2) var(--space-3);
  border-bottom: 1px solid var(--line);
}

.inspector-target-drawer-search .search-input,
.inspector-target-drawer-search .search-input input {
  width: 100%;
}

.inspector-target-drawer-search .search-input input {
  font-weight: 400;
}

.inspector-target-drawer-list {
  min-height: 0;
  overflow: hidden;
}

.inspector-target-drawer-list .stream-table {
  height: 100%;
  max-height: none;
  border: 0;
  border-radius: 0;
}

.inspector-target-drawer-empty {
  display: grid;
  height: 100%;
  place-items: center;
  color: var(--text-muted);
}

@keyframes dashboard-target-fade-in {
  from { background: transparent; }
}

@keyframes dashboard-target-slide-in {
  from { transform: translateX(100%); }
}

@media (max-width: 720px) {
  .inspector-target-drawer {
    width: 100vw;
  }

  .dashboard-detail-target-label,
  .dashboard-detail-target-mode {
    display: none;
  }
}

